-- 0024: questions approved in the depot since the last migration (500).
-- Generated by scripts/depot-to-sql.py. Applied by the founder. Safe to apply twice.

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'An entrepreneur is best defined as a person who',
  '[{"id": "a", "text": "identifies an opportunity and organises resources to create a business, bearing the risk"}, {"id": "b", "text": "works for a salary in a large firm"}, {"id": "c", "text": "inherits a business and runs it unchanged"}, {"id": "d", "text": "lends money to businesses at a fixed interest"}]'::jsonb, 'a', 'The core of entrepreneurship is spotting an opportunity, pooling resources and accepting risk. A lender earns interest without carrying the business risk.', 2,
  'general-studies/ent211', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'ent211' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/ent211' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'An employee who develops new ideas inside an existing company is called an',
  '[{"id": "a", "text": "entrepreneur"}, {"id": "b", "text": "stakeholder"}, {"id": "c", "text": "franchisee"}, {"id": "d", "text": "intrapreneur"}]'::jsonb, 'd', '''Intra'' means within: an intrapreneur innovates inside a firm. An entrepreneur starts a new venture of their own, which is the nearest wrong choice.', 3,
  'general-studies/ent211', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'ent211' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/ent211' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'In a SWOT analysis, which pair describes factors that originate OUTSIDE the business?',
  '[{"id": "a", "text": "Strengths and weaknesses"}, {"id": "b", "text": "Strengths and opportunities"}, {"id": "c", "text": "Opportunities and threats"}, {"id": "d", "text": "Weaknesses and threats"}]'::jsonb, 'c', 'Strengths and weaknesses are internal. Opportunities and threats are external, such as new competitors or changes in regulation.', 3,
  'general-studies/ent211', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'ent211' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/ent211' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'A business owned and run by one person, who bears unlimited liability, is a',
  '[{"id": "a", "text": "limited liability company"}, {"id": "b", "text": "sole proprietorship"}, {"id": "c", "text": "cooperative society"}, {"id": "d", "text": "public corporation"}]'::jsonb, 'b', 'A sole proprietor has no legal separation from the business, so personal assets can be used to pay debts. A limited liability company limits that exposure.', 2,
  'general-studies/ent211', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'ent211' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/ent211' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A product that sells for N500 has a variable cost of N300 per unit and fixed costs of N100,000. How many units give break-even?',
  '[{"id": "a", "text": "200"}, {"id": "b", "text": "500"}, {"id": "c", "text": "333"}, {"id": "d", "text": "1000"}]'::jsonb, 'b', 'Break-even units = fixed costs / (price - variable cost) = 100,000 / 200 = 500. Dividing by the price alone gives 200, which ignores variable cost. Dividing by the variable cost gives 333, and 1,000 would need a margin of only N100 per unit.', 4,
  'general-studies/ent211', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'ent211' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/ent211' and k.depot_qid = 'q005')
order by c.id limit 1;

