  '[{"id": "a", "text": "incremental innovation"}, {"id": "b", "text": "radical innovation"}, {"id": "c", "text": "imitation"}, {"id": "d", "text": "liquidation"}]'::jsonb, 'a', 'Incremental innovation improves what already exists. Radical innovation creates something new to the market, so it is the nearest wrong choice.', 3,
  'general-studies/ent211', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'ent211' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/ent211' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
