insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'In a business plan, the section that briefly states the whole venture for a busy reader is the',
  '[{"id": "a", "text": "executive summary"}, {"id": "b", "text": "appendix"}, {"id": "c", "text": "financial projection"}, {"id": "d", "text": "market survey"}]'::jsonb, 'a', 'The executive summary condenses the plan''s key points and is usually written last but placed first. The financial projection is only one part of what it summarises.', 2,
