insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A start-up that sells 400 units at N250, with fixed costs of N30,000 and variable cost of N100 per unit, makes a profit of',
  '[{"id": "a", "text": "N70,000"}, {"id": "b", "text": "N10,000"}, {"id": "c", "text": "N100,000"}, {"id": "d", "text": "N30,000"}]'::jsonb, 'd', 'Revenue = 400 x 250 = 100,000. Total cost = 30,000 + 400 x 100 = 70,000. Profit = 30,000. Forgetting fixed costs gives N60,000, and subtracting only variable cost gives the wrong figure.', 4,
  'general-studies/ent312', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'ent312' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/ent312' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
