  '[{"id": "a", "text": "market penetration"}, {"id": "b", "text": "product diversification"}, {"id": "c", "text": "market segmentation"}, {"id": "d", "text": "price skimming"}]'::jsonb, 'c', 'Segmentation groups customers by traits such as age, income or location. Penetration is about winning a bigger share of an existing market.', 3,
  'general-studies/ent312', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
