  '[{"id": "a", "text": "profit is highest"}, {"id": "b", "text": "total revenue equals total cost"}, {"id": "c", "text": "fixed costs are zero"}, {"id": "d", "text": "variable costs equal fixed costs"}]'::jsonb, 'b', 'At break-even there is neither profit nor loss. Profit is not highest there, and the point has no requirement that variable and fixed costs be equal.', 3,
  'general-studies/ent312', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'ent312' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/ent312' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Choose the sentence in which the verb agrees correctly with its subject.',
  '[{"id": "a", "text": "Neither the lecturer nor the students were present at the hall."}, {"id": "b", "text": "Neither the lecturer nor the students was present at the hall."}, {"id": "c", "text": "Neither the lecturer nor the students is present at the hall."}, {"id": "d", "text": "Neither the lecturer nor the students has been present at the hall."}]'::jsonb, 'a', 'With ''neither...nor'', the verb agrees with the subject nearest to it. ''Students'' is plural, so ''were'' is correct; ''was'' would only fit if the nearer subject were singular.', 3,
  'general-studies/gst111', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst111' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'In the sentence ''The wind whispered through the trees'', the figure of speech used is',
  '[{"id": "a", "text": "metaphor"}, {"id": "b", "text": "simile"}, {"id": "c", "text": "hyperbole"}, {"id": "d", "text": "personification"}]'::jsonb, 'd', 'A human action (whispering) is given to the wind, which is personification. It is not a metaphor because nothing is declared to BE something else, and not a simile because there is no ''like'' or ''as''.', 2,
  'general-studies/gst111', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst111' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'The word ''ephemeral'' is closest in meaning to',
  '[{"id": "a", "text": "everlasting"}, {"id": "b", "text": "fragile"}, {"id": "c", "text": "short-lived"}, {"id": "d", "text": "mysterious"}]'::jsonb, 'c', 'Ephemeral describes something that lasts for a very short time. ''Everlasting'' is its antonym, and the nearest wrong choice because a careless reader may match it to the wrong pole of the meaning.', 3,
  'general-studies/gst111', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst111' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'In a well-constructed paragraph, the topic sentence',
  '[{"id": "a", "text": "gives the final example in the paragraph"}, {"id": "b", "text": "states the main idea that the other sentences develop"}, {"id": "c", "text": "summarises the whole essay in one line"}, {"id": "d", "text": "introduces a new and unrelated point"}]'::jsonb, 'b', 'The topic sentence carries the controlling idea of its paragraph. A summary of the whole essay belongs in the conclusion, not in every paragraph.', 2,
  'general-studies/gst111', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst111' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Which of the following sentences is a comma splice (a punctuation error)?',
  '[{"id": "a", "text": "The lecture ended early, so the students went home."}, {"id": "b", "text": "The lecture ended early, the students went home."}, {"id": "c", "text": "Because the lecture ended early, the students went home."}, {"id": "d", "text": "The lecture ended early; therefore the students went home."}]'::jsonb, 'b', 'A comma splice joins two complete sentences with a comma alone. Adding a coordinating conjunction (''so'') or a subordinating word (''because'') fixes it, and a semicolon with a linking word is also correct.', 3,
  'general-studies/gst111', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst111' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Contextual / rhetoric']::text[], 'Which of these sentences has NO dangling modifier?',
  '[{"id": "a", "text": "Walking to school, Ada was caught in the rain."}, {"id": "b", "text": "Walking to school, the rain began to fall."}, {"id": "c", "text": "Having finished the exam, the bell rang."}, {"id": "d", "text": "Reading the notice, the gate was locked."}]'::jsonb, 'a', 'The opening phrase must describe the subject that follows it. Ada is the one walking. In the others, the rain, the bell and the gate cannot walk, finish an exam or read. In each wrong sentence the opening phrase is attached to the wrong noun, so the sentence says something impossible.', 4,
  'general-studies/gst111', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst111' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Contextual / rhetoric']::text[], 'Which opening is most suitable for a formal letter of application?',
  '[{"id": "a", "text": "Hey, I wanna apply for the lab job you posted."}, {"id": "b", "text": "Good day to you! I am just checking if there is any job."}, {"id": "c", "text": "To whom it may concern: please give me a job now."}, {"id": "d", "text": "I write to apply for the position of laboratory assistant advertised in your office."}]'::jsonb, 'd', 'Formal writing uses complete, polite, precise sentences. The slang version is wrong for the register, and the ''just checking'' version is vague about what is being applied for.', 2,
  'general-studies/gst111', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst111' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'Running your eyes quickly over a passage to find one fact, such as a date, is called',
  '[{"id": "a", "text": "skimming"}, {"id": "b", "text": "intensive reading"}, {"id": "c", "text": "scanning"}, {"id": "d", "text": "critical reading"}]'::jsonb, 'c', 'Scanning looks for a specific detail. Skimming is the nearest wrong choice: it gives the general gist and does not hunt for one particular item.', 3,
  'general-studies/gst111', 'q008'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst111' and k.depot_qid = 'q008')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Contextual / rhetoric']::text[], 'Which of these expressions is redundant?',
  '[{"id": "a", "text": "return home"}, {"id": "b", "text": "go back"}, {"id": "c", "text": "return back"}, {"id": "d", "text": "come in"}]'::jsonb, 'c', '''Return'' already means ''go back'', so ''return back'' repeats the idea. ''Go back'' is fine because ''go'' carries no sense of returning. ''Return home'' is sound because ''home'' adds a destination, and ''come in'' repeats nothing.', 3,
  'general-studies/gst111', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst111' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Procedural / supply chain']::text[], '''Yours faithfully'' should close a formal letter that begins with',
  '[{"id": "a", "text": "Dear Mr Bello"}, {"id": "b", "text": "Dear Sir or Madam"}, {"id": "c", "text": "Dear Aunty"}, {"id": "d", "text": "Dear Dr Okeke"}]'::jsonb, 'b', 'By convention, ''Dear Sir/Madam'' pairs with ''Yours faithfully'', and a salutation using a name pairs with ''Yours sincerely''. ''Yours sincerely'' is the nearest wrong close, and it belongs with the named salutations.', 3,
  'general-studies/gst111', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst111' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'The Northern and Southern Protectorates of Nigeria were amalgamated in',
  '[{"id": "a", "text": "1914"}, {"id": "b", "text": "1900"}, {"id": "c", "text": "1922"}, {"id": "d", "text": "1960"}]'::jsonb, 'a', 'Lord Lugard oversaw the amalgamation of 1 January 1914. 1960 is the year of independence, the nearest confusion, but that is a different event.', 2,
  'general-studies/gst112', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
