  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst112' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'Which three ethnic groups are the largest in Nigeria?',
  '[{"id": "a", "text": "Hausa-Fulani, Ijaw and Kanuri"}, {"id": "b", "text": "Yoruba, Tiv and Efik"}, {"id": "c", "text": "Igbo, Edo and Nupe"}, {"id": "d", "text": "Hausa-Fulani, Yoruba and Igbo"}]'::jsonb, 'd', 'Hausa-Fulani, Yoruba and Igbo together make up the largest shares of the population. Ijaw and Kanuri are major groups but smaller, which is why the first wrong option is tempting.', 2,
  'general-studies/gst112', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst112' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst112' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Contextual / rhetoric']::text[], 'The Sokoto Caliphate was founded after a jihad led by',
  '[{"id": "a", "text": "Rabih Fadlallah"}, {"id": "b", "text": "Mai Idris Alooma"}, {"id": "c", "text": "Usman dan Fodio"}, {"id": "d", "text": "Shehu Garba of Bornu"}]'::jsonb, 'c', 'Usman dan Fodio began the Fulani jihad in 1804 and founded the Sokoto Caliphate. Mai Idris Alooma was a ruler of Kanem-Bornu centuries earlier, so he is the nearest wrong name.', 3,
  'general-studies/gst112', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst112' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst112' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Abstract / Visual']::text[], 'The Nok culture of central Nigeria is best known for',
  '[{"id": "a", "text": "bronze plaques of royal courts"}, {"id": "b", "text": "terracotta sculptures and early iron smelting"}, {"id": "c", "text": "stone-walled cities of the savannah"}, {"id": "d", "text": "rock paintings of the Sahara"}]'::jsonb, 'b', 'Nok produced terracotta figures and is linked to early iron working in West Africa. Bronze plaques belong to Benin, which is why they are the nearest wrong answer.', 3,
  'general-studies/gst112', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst112' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst112' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'The traditional ruler of the Benin Kingdom is called the',
  '[{"id": "a", "text": "Ooni"}, {"id": "b", "text": "Oba"}, {"id": "c", "text": "Emir"}, {"id": "d", "text": "Obi"}]'::jsonb, 'b', 'The ruler of Benin is the Oba. The Ooni rules Ife, and he is the nearest wrong choice because both are Southern titles that are easy to confuse.', 2,
  'general-studies/gst112', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
