  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst112' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'Nigeria attained independence from Britain on',
  '[{"id": "a", "text": "1 October 1960"}, {"id": "b", "text": "15 January 1966"}, {"id": "c", "text": "1 October 1963"}, {"id": "d", "text": "27 May 1967"}]'::jsonb, 'a', 'Independence was on 1 October 1960. 1 October 1963 is when Nigeria became a republic, the nearest wrong date, and that event changed the head of state rather than ending colonial rule.', 2,
  'general-studies/gst112', 'q006'
