  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst112' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Procedural / supply chain']::text[], 'Nigeria''s capital was officially moved from Lagos to Abuja in',
  '[{"id": "a", "text": "1960"}, {"id": "b", "text": "1976"}, {"id": "c", "text": "2003"}, {"id": "d", "text": "1991"}]'::jsonb, 'd', 'The move became official on 12 December 1991. The decision to create a new capital was announced in 1976, which is why 1976 is the nearest wrong choice: it marks the decision, not the move.', 4,
  'general-studies/gst112', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst112' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst112' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Contextual / rhetoric']::text[], 'Which statement about languages in Nigeria is correct?',
  '[{"id": "a", "text": "Nigeria has fewer than ten languages and Hausa is the official language"}, {"id": "b", "text": "Yoruba is the only language taught in all schools"}, {"id": "c", "text": "Nigeria has several hundred languages, and English is the official language"}, {"id": "d", "text": "English was replaced as the official language in 1960"}]'::jsonb, 'c', 'Linguists count about five hundred languages in Nigeria, and English is the official language used in government and education. Hausa, Yoruba and Igbo are major national languages, but none is the official language.', 3,
  'general-studies/gst112', 'q008'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst112' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst112' and k.depot_qid = 'q008')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Contextual / rhetoric']::text[], 'Which of these is a reason Nigeria''s cultural diversity is considered a national asset?',
  '[{"id": "a", "text": "It guarantees that all citizens speak one language"}, {"id": "b", "text": "It removes the need for a central government"}, {"id": "c", "text": "It supplies a wide range of arts, food, music and trade networks"}, {"id": "d", "text": "It prevents any group from migrating"}]'::jsonb, 'c', 'Diversity enriches the arts, cuisine, festivals and commerce. Saying it guarantees one language contradicts the meaning of diversity.', 3,
  'general-studies/gst112', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst112' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst112' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Contextual / rhetoric']::text[], 'Traditional marriage among most Nigerian peoples is best described as',
  '[{"id": "a", "text": "a purely private contract with no family role"}, {"id": "b", "text": "a union between two families as well as two individuals"}, {"id": "c", "text": "a legal act that only a court can perform"}, {"id": "d", "text": "a ceremony restricted to one ethnic group"}]'::jsonb, 'b', 'Across Nigerian cultures, marriage joins families and involves rites such as bride price or introductions. Treating it as a private contract misses the role of the extended family.', 2,
  'general-studies/gst112', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
