select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Which branch of philosophy studies the nature of knowledge and how we know things?',
  '[{"id": "a", "text": "Epistemology"}, {"id": "b", "text": "Metaphysics"}, {"id": "c", "text": "Ethics"}, {"id": "d", "text": "Aesthetics"}]'::jsonb, 'a', 'Epistemology asks what knowledge is and how it is justified. Metaphysics asks about the nature of reality, which is the nearest wrong choice.', 2,
  'general-studies/gst212', 'q001'
