insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Mathematical Proofs']::text[], 'A syllogism: ''All students are learners. Ada is a student. Therefore Ada is a learner.'' This argument is',
  '[{"id": "a", "text": "invalid, because the premises are false"}, {"id": "b", "text": "inductive, because it reasons from many examples"}, {"id": "c", "text": "a fallacy of equivocation"}, {"id": "d", "text": "valid, because the conclusion follows from the premises"}]'::jsonb, 'd', 'In a valid deductive argument the conclusion must follow if the premises are true, and it does here. It is deductive, not inductive, because it does not generalise from examples.', 3,
  'general-studies/gst212', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst212' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst212' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Which statement is an example of an ad hominem fallacy?',
  '[{"id": "a", "text": "''Taxes are high, so the economy must be doing badly.''"}, {"id": "b", "text": "''If we allow one exception, soon there will be no rule.''"}, {"id": "c", "text": "''Do not trust his argument about taxes; he is a failed businessman.''"}, {"id": "d", "text": "''Everyone believes it, so it must be true.''"}]'::jsonb, 'c', 'An ad hominem attacks the person instead of the argument. ''Everyone believes it'' is an appeal to popularity, which is the nearest wrong option.', 3,
  'general-studies/gst212', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst212' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst212' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'The statement ''I think, therefore I am'' is associated with',
  '[{"id": "a", "text": "David Hume"}, {"id": "b", "text": "Rene Descartes"}, {"id": "c", "text": "John Locke"}, {"id": "d", "text": "Plato"}]'::jsonb, 'b', 'Descartes used the cogito as an unshakeable starting point. Hume and Locke were empiricists who stressed experience over such a rationalist starting point.', 3,
  'general-studies/gst212', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst212' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst212' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The law of non-contradiction states that',
  '[{"id": "a", "text": "every statement is either true or false"}, {"id": "b", "text": "a statement cannot be both true and false in the same sense at the same time"}, {"id": "c", "text": "every effect has a cause"}, {"id": "d", "text": "all knowledge comes from the senses"}]'::jsonb, 'b', 'Non-contradiction forbids a statement and its denial from both being true together. ''Every statement is either true or false'' is the law of excluded middle, the nearest wrong answer.', 4,
  'general-studies/gst212', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst212' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst212' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Reasoning from a general principle to a specific conclusion is called',
  '[{"id": "a", "text": "deduction"}, {"id": "b", "text": "induction"}, {"id": "c", "text": "abduction"}, {"id": "d", "text": "intuition"}]'::jsonb, 'a', 'Deduction moves from general to specific. Induction does the reverse, moving from observed cases to a general claim.', 2,
  'general-studies/gst212', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst212' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst212' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'Socrates is best known for the method of',
  '[{"id": "a", "text": "lecturing from written notes"}, {"id": "b", "text": "writing laws for the city"}, {"id": "c", "text": "measuring objects by experiment"}, {"id": "d", "text": "questioning to expose assumptions and reach clearer ideas"}]'::jsonb, 'd', 'The Socratic method is a disciplined series of questions. Socrates wrote nothing himself, so a method based on lecturing from notes does not fit him.', 3,
  'general-studies/gst212', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
