insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The branch of philosophy that studies right and wrong conduct is',
  '[{"id": "a", "text": "logic"}, {"id": "b", "text": "metaphysics"}, {"id": "c", "text": "ethics"}, {"id": "d", "text": "epistemology"}]'::jsonb, 'c', 'Ethics concerns moral conduct. Logic studies the structure of correct reasoning, which is the nearest wrong choice.', 2,
