insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Mathematical Proofs']::text[], 'An argument is SOUND when it is',
  '[{"id": "a", "text": "valid even if the premises are false"}, {"id": "b", "text": "persuasive to most listeners"}, {"id": "c", "text": "valid and all of its premises are true"}, {"id": "d", "text": "short and simple"}]'::jsonb, 'c', 'Soundness needs both validity and true premises. A valid argument with a false premise is valid but not sound.', 4,
  'general-studies/gst212', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst212' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst212' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Contextual / rhetoric']::text[], 'Which is a major concern of existentialist thought?',
  '[{"id": "a", "text": "Proving that numbers exist independently"}, {"id": "b", "text": "The individual''s freedom and responsibility to create meaning"}, {"id": "c", "text": "Recording the history of kings"}, {"id": "d", "text": "Classifying animals by their traits"}]'::jsonb, 'b', 'Existentialism centres on individual freedom, choice and meaning, as in the work of Sartre. Mathematical realism is a separate topic in the philosophy of mathematics. Recording the history of kings belongs to political history, and classifying animals by their traits is taxonomy in biology.', 4,
  'general-studies/gst212', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst212' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst212' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Conflict is best described as',
  '[{"id": "a", "text": "a disagreement or clash between parties with incompatible interests, goals or values"}, {"id": "b", "text": "the absence of war between states"}, {"id": "c", "text": "a violent act that must involve weapons"}, {"id": "d", "text": "a decision made by a court"}]'::jsonb, 'a', 'Conflict need not be violent. Defining it as war or weapons use confuses one extreme form with the whole concept.', 2,
  'general-studies/gst312', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst312' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst312' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'In Galtung''s terms, ''negative peace'' means',
  '[{"id": "a", "text": "the presence of justice and equity"}, {"id": "b", "text": "a permanent agreement among all groups"}, {"id": "c", "text": "the dominance of one group over others"}, {"id": "d", "text": "the absence of direct violence"}]'::jsonb, 'd', 'Negative peace is simply no direct violence. Positive peace adds justice and removing causes of violence, so it is the nearest wrong choice.', 4,
  'general-studies/gst312', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst312' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst312' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'A neutral third party who helps disputants reach their OWN agreement, without imposing a decision, is a',
  '[{"id": "a", "text": "arbitrator"}, {"id": "b", "text": "judge"}, {"id": "c", "text": "mediator"}, {"id": "d", "text": "prosecutor"}]'::jsonb, 'c', 'A mediator facilitates talks, and the parties decide the outcome. An arbitrator hears the case and gives a binding decision, so it is the nearest wrong choice.', 3,
  'general-studies/gst312', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst312' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst312' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'Which method of settlement produces a binding decision made by a neutral third party chosen by the parties?',
  '[{"id": "a", "text": "Negotiation"}, {"id": "b", "text": "Arbitration"}, {"id": "c", "text": "Mediation"}, {"id": "d", "text": "Avoidance"}]'::jsonb, 'b', 'In arbitration the arbitrator decides and the decision binds. Negotiation and mediation leave the outcome to the parties.', 3,
  'general-studies/gst312', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst312' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst312' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'A conflict approach in which both parties give up part of what they want to reach a deal is',
  '[{"id": "a", "text": "competition"}, {"id": "b", "text": "compromise"}, {"id": "c", "text": "accommodation"}, {"id": "d", "text": "avoidance"}]'::jsonb, 'b', 'In compromise each side concedes something. In accommodation only one side yields, so it is the nearest wrong answer.', 3,
  'general-studies/gst312', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst312' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst312' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The ''zero-sum'' view of conflict assumes that',
  '[{"id": "a", "text": "one party''s gain is the other party''s loss"}, {"id": "b", "text": "both parties can win together"}, {"id": "c", "text": "no party can lose anything"}, {"id": "d", "text": "outside help is never needed"}]'::jsonb, 'a', 'Zero-sum means the total is fixed, so a gain for one side equals a loss for the other. A win-win approach rejects that assumption. ''Both parties can win together'' describes a positive-sum outcome, which is the opposite assumption.', 4,
  'general-studies/gst312', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst312' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst312' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'The 2009 amnesty programme in Nigeria was a response to unrest in the',
  '[{"id": "a", "text": "Lake Chad basin"}, {"id": "b", "text": "Jos Plateau"}, {"id": "c", "text": "Cross River highlands"}, {"id": "d", "text": "Niger Delta"}]'::jsonb, 'd', 'The federal government''s 2009 amnesty offered militants in the Niger Delta disarmament and rehabilitation. The Lake Chad basin and Jos Plateau have different conflicts with different responses.', 3,
  'general-studies/gst312', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst312' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst312' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'Which regional body has played a major peacekeeping role in West Africa?',
  '[{"id": "a", "text": "OPEC"}, {"id": "b", "text": "CARICOM"}, {"id": "c", "text": "ECOWAS"}, {"id": "d", "text": "NATO"}]'::jsonb, 'c', 'ECOWAS, through its monitoring group ECOMOG, intervened in conflicts in Liberia and Sierra Leone. OPEC is an oil producers'' organisation. CARICOM is a Caribbean trade community and NATO is a North Atlantic military alliance, so neither is a West African body.', 2,
  'general-studies/gst312', 'q008'
