  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst312' and k.depot_qid = 'q008')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'Active listening during a dispute means',
  '[{"id": "a", "text": "preparing your reply while the other person speaks"}, {"id": "b", "text": "interrupting to correct errors"}, {"id": "c", "text": "paying full attention and restating what the other person said to confirm understanding"}, {"id": "d", "text": "agreeing with everything said"}]'::jsonb, 'c', 'It shows the speaker was understood and lowers tension. Preparing a reply while someone speaks is the nearest wrong answer, since it feels like listening but is not.', 2,
  'general-studies/gst312', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
