  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Contextual / rhetoric']::text[], 'Which of these is a CAUSE of communal conflict that peace education tries to reduce?',
  '[{"id": "a", "text": "Shared markets between neighbours"}, {"id": "b", "text": "Unequal access to land and resources between groups"}, {"id": "c", "text": "Joint festivals"}, {"id": "d", "text": "Inter-group marriages"}]'::jsonb, 'b', 'Competition over land and resources is a common driver of communal conflict. Shared markets, festivals and marriages tend to build ties across groups.', 3,
  'general-studies/gst312', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'general-studies' and d.slug = 'general-studies' and c.slug = 'gst312' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'general-studies/gst312' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'In the human female, primary oocytes are arrested from fetal life until puberty at the stage of',
  '[{"id": "a", "text": "prophase of meiosis I"}, {"id": "b", "text": "metaphase of meiosis II"}, {"id": "c", "text": "anaphase of mitosis"}, {"id": "d", "text": "telophase of meiosis I"}]'::jsonb, 'a', 'Primary oocytes begin meiosis I before birth and stop in prophase I until ovulation. The arrest in metaphase II applies to the secondary oocyte, which finishes meiosis only if fertilised.', 4,
  'medicine/ant214', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'ant214' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant214' and k.depot_qid = 'q001')
order by c.id limit 1;

