  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Abstract / Visual']::text[], 'The primary visual cortex lies around the',
  '[{"id": "a", "text": "lateral sulcus"}, {"id": "b", "text": "calcarine sulcus in the occipital lobe"}, {"id": "c", "text": "central sulcus"}, {"id": "d", "text": "hippocampal fissure"}]'::jsonb, 'b', 'Visual information from the contralateral visual field is received around the calcarine sulcus. The lateral sulcus separates the temporal lobe from the frontal and parietal lobes, and the central sulcus separates motor from sensory cortex.', 2,
  'medicine/ant315', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'ant315' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant315' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The fibres of the corticospinal tract cross to the opposite side mainly at the',
  '[{"id": "a", "text": "anterior commissure of the spinal cord"}, {"id": "b", "text": "pyramidal decussation in the lower medulla"}, {"id": "c", "text": "optic chiasm"}, {"id": "d", "text": "internal capsule"}]'::jsonb, 'b', 'About 85 to 90 percent of the fibres cross at the pyramids. For that reason, a lesion above the decussation causes weakness on the opposite side of the body.', 3,
  'medicine/ant315', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'ant315' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant315' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Abstract / Visual']::text[], 'A patient has a stroke in the left internal capsule. The expected motor deficit is',
  '[{"id": "a", "text": "weakness of the right side of the body"}, {"id": "b", "text": "weakness of the left side of the body"}, {"id": "c", "text": "weakness of both legs only"}, {"id": "d", "text": "no motor deficit"}]'::jsonb, 'a', 'The internal capsule is above the pyramidal decussation, so the corticospinal fibres have not yet crossed. The left capsule therefore controls the right side.', 3,
  'medicine/ant315', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'ant315' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant315' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The dorsal column-medial lemniscus pathway carries',
  '[{"id": "a", "text": "pain and temperature"}, {"id": "b", "text": "unconscious proprioception to the cerebellum"}, {"id": "c", "text": "motor commands to muscle"}, {"id": "d", "text": "fine touch, vibration and conscious proprioception"}]'::jsonb, 'd', 'These fibres ascend ipsilaterally in the cord and cross in the medulla. Pain and temperature travel in the spinothalamic tract, which is the nearest wrong choice.', 4,
  'medicine/ant315', 'q007'
