insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The spinothalamic tract carries pain and temperature, and its fibres cross',
  '[{"id": "a", "text": "in the medulla"}, {"id": "b", "text": "in the cerebral cortex"}, {"id": "c", "text": "within a few segments of entering the spinal cord"}, {"id": "d", "text": "in the pons"}]'::jsonb, 'c', 'Second-order neurones cross through the anterior white commissure soon after entry. Crossing in the medulla is a feature of the dorsal column pathway.', 4,
  'medicine/ant315', 'q008'
from cgpa.courses c
