insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Parkinson''s disease results mainly from degeneration of dopaminergic neurones in the',
  '[{"id": "a", "text": "hippocampus"}, {"id": "b", "text": "cerebellar cortex"}, {"id": "c", "text": "substantia nigra (pars compacta)"}, {"id": "d", "text": "occipital cortex"}]'::jsonb, 'c', 'Loss of dopamine in the nigrostriatal pathway disrupts basal ganglia control, causing tremor, rigidity and bradykinesia. The hippocampus handles memory, the cerebellar cortex coordinates movement and the occipital cortex processes vision. None is the site of dopamine loss in Parkinson''s disease.', 3,
  'medicine/ant315', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'ant315' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant315' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Which of these is part of the basal ganglia?',
  '[{"id": "a", "text": "Hippocampus"}, {"id": "b", "text": "Caudate nucleus"}, {"id": "c", "text": "Pons"}, {"id": "d", "text": "Pineal gland"}]'::jsonb, 'b', 'The caudate nucleus, putamen and globus pallidus form the basal ganglia. The pons belongs to the brainstem, which is the nearest wrong choice.', 3,
  'medicine/ant315', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
