  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant315' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The thalamus acts as a relay station for sensory information to the cortex for all senses EXCEPT',
  '[{"id": "a", "text": "olfaction (smell)"}, {"id": "b", "text": "vision"}, {"id": "c", "text": "hearing"}, {"id": "d", "text": "touch"}]'::jsonb, 'a', 'Olfactory fibres reach the olfactory cortex directly without a thalamic relay. The other senses do relay in specific thalamic nuclei. Vision relays in the lateral geniculate nucleus, hearing in the medial geniculate nucleus and touch in the ventral posterior nuclei.', 3,
  'medicine/ant315', 'q011'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'ant315' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant315' and k.depot_qid = 'q011')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A lesion of the right cerebellar hemisphere produces incoordination (ataxia) on the',
  '[{"id": "a", "text": "left side of the body"}, {"id": "b", "text": "both sides equally"}, {"id": "c", "text": "face only"}, {"id": "d", "text": "right side of the body (same side)"}]'::jsonb, 'd', 'The cerebellum acts ipsilaterally because of a double crossing of its pathways. The effect on the left side would apply to a cerebral lesion.', 4,
  'medicine/ant315', 'q012'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
