  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant315' and k.depot_qid = 'q012')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'Which cranial nerve supplies the lateral rectus muscle of the eye?',
  '[{"id": "a", "text": "Oculomotor (III)"}, {"id": "b", "text": "Trochlear (IV)"}, {"id": "c", "text": "Trigeminal (V)"}, {"id": "d", "text": "Abducens (VI)"}]'::jsonb, 'd', 'The rule is LR6 SO4: the lateral rectus is supplied by VI, the superior oblique by IV, and the rest by III. Damage to VI stops the eye from moving outward. The oculomotor nerve supplies most of the other eye muscles, the trochlear nerve supplies the superior oblique, and the trigeminal nerve carries facial sensation and moves the jaw.', 3,
  'medicine/ant315', 'q013'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'ant315' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant315' and k.depot_qid = 'q013')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'Taste from the anterior two-thirds of the tongue is carried by the',
  '[{"id": "a", "text": "glossopharyngeal nerve"}, {"id": "b", "text": "hypoglossal nerve"}, {"id": "c", "text": "facial nerve, through the chorda tympani"}, {"id": "d", "text": "vagus nerve"}]'::jsonb, 'c', 'The chorda tympani, a branch of the facial nerve, carries taste from the front of the tongue. The glossopharyngeal nerve serves the posterior third.', 4,
  'medicine/ant315', 'q014'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
