select c.id, array['Pragmatic']::text[], array['Abstract / Visual']::text[], 'The anterior communicating artery of the circle of Willis connects the',
  '[{"id": "a", "text": "two posterior cerebral arteries"}, {"id": "b", "text": "two anterior cerebral arteries"}, {"id": "c", "text": "internal carotid and posterior cerebral arteries"}, {"id": "d", "text": "the basilar and vertebral arteries"}]'::jsonb, 'b', 'It joins the anterior cerebral arteries across the midline at the front of the circle. The posterior communicating arteries connect the carotid and posterior systems.', 4,
  'medicine/ant315', 'q015'
from cgpa.courses c
