insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Occlusion of the middle cerebral artery on the left (dominant) side typically causes',
  '[{"id": "a", "text": "right-sided weakness affecting the face and arm more than the leg, with aphasia"}, {"id": "b", "text": "left-sided weakness with a leg predominance"}, {"id": "c", "text": "isolated loss of vision on the left"}, {"id": "d", "text": "bilateral leg weakness only"}]'::jsonb, 'a', 'The face and arm areas lie on the lateral surface supplied by the middle cerebral artery. The leg area lies medially and is supplied by the anterior cerebral artery. Left-sided weakness would need a lesion on the right, and weakness that favours the leg points to the anterior cerebral artery.', 5,
  'medicine/ant315', 'q016'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'ant315' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant315' and k.depot_qid = 'q016')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Abstract / Visual']::text[], 'The cerebral aqueduct connects the',
  '[{"id": "a", "text": "third and fourth ventricles"}, {"id": "b", "text": "lateral and third ventricles"}, {"id": "c", "text": "fourth ventricle and subarachnoid space"}, {"id": "d", "text": "the two lateral ventricles"}]'::jsonb, 'a', 'CSF flows from the lateral ventricles through the interventricular foramina into the third ventricle, then through the aqueduct to the fourth ventricle. Blockage of the aqueduct leads to hydrocephalus.', 4,
  'medicine/ant315', 'q017'
from cgpa.courses c
