insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'In an adult, the spinal cord ends (conus medullaris) at about the level of',
  '[{"id": "a", "text": "T1 vertebra"}, {"id": "b", "text": "S2 vertebra"}, {"id": "c", "text": "L1 to L2 vertebra"}, {"id": "d", "text": "C7 vertebra"}]'::jsonb, 'c', 'The cord is shorter than the vertebral column, so lumbar puncture is done below L2 (usually L3 to L4) to avoid the cord. T1 and C7 are far too high, and S2 is where the dural sac ends, not the cord.', 4,
  'medicine/ant315', 'q019'
