  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/ant315' and k.depot_qid = 'q019')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'The sympathetic nervous system has its preganglionic cell bodies in the',
  '[{"id": "a", "text": "craniosacral region"}, {"id": "b", "text": "thoracolumbar (T1 to L2) spinal cord"}, {"id": "c", "text": "cerebral cortex"}, {"id": "d", "text": "cerebellum"}]'::jsonb, 'b', 'The craniosacral outflow (cranial nerves III, VII, IX, X and S2 to S4) belongs to the parasympathetic system.', 3,
  'medicine/ant315', 'q020'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
