insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Which statement is part of the cell theory?',
  '[{"id": "a", "text": "All cells arise from pre-existing cells"}, {"id": "b", "text": "All organisms are made of a single cell"}, {"id": "c", "text": "Cells are visible to the naked eye"}, {"id": "d", "text": "Viruses are the basic units of life"}]'::jsonb, 'a', 'Cell theory says living things are made of cells, the cell is the basic unit of life, and cells come from pre-existing cells. It does not say that every organism is unicellular, since many are multicellular.', 2,
  'medicine/bio101', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio101' and k.depot_qid = 'q001')
order by c.id limit 1;

