select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A key difference between prokaryotic and eukaryotic cells is that prokaryotes',
  '[{"id": "a", "text": "have no genetic material"}, {"id": "b", "text": "have no cell membrane"}, {"id": "c", "text": "are always larger than eukaryotes"}, {"id": "d", "text": "have no membrane-bound nucleus"}]'::jsonb, 'd', 'Prokaryotic DNA lies free in the cytoplasm, in a nucleoid. They do have genetic material and a cell membrane, and they are generally smaller than eukaryotic cells.', 2,
  'medicine/bio101', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
