  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The forelimbs of a human, a bat and a whale have the same bone structure but different functions. This is evidence of',
  '[{"id": "a", "text": "homologous structures from a common ancestor"}, {"id": "b", "text": "analogous structures from convergent evolution"}, {"id": "c", "text": "vestigial structures"}, {"id": "d", "text": "spontaneous generation"}]'::jsonb, 'a', 'Same underlying structure with different uses points to common ancestry. Analogous structures have similar function but different origins, for example the wings of insects and birds.', 3,
  'medicine/bio102', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio102' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio102' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'In a population in Hardy-Weinberg equilibrium, 4% of individuals are homozygous recessive (aa). The frequency of heterozygotes (Aa) is',
  '[{"id": "a", "text": "0.16"}, {"id": "b", "text": "0.64"}, {"id": "c", "text": "0.20"}, {"id": "d", "text": "0.32"}]'::jsonb, 'd', 'q^2 = 0.04, so q = 0.2 and p = 0.8. Heterozygotes = 2pq = 2 x 0.8 x 0.2 = 0.32. The value 0.20 is just q. The value 0.64 is the frequency of homozygous dominant individuals (p squared), and 0.16 is the square of 0.4, which has no meaning here.', 5,
  'medicine/bio102', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio102' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio102' and k.depot_qid = 'q007')
order by c.id limit 1;

