  '[{"id": "a", "text": "starch"}, {"id": "b", "text": "protein"}, {"id": "c", "text": "sodium chloride"}, {"id": "d", "text": "vitamin C (ascorbic acid)"}]'::jsonb, 'd', 'Vitamin C reduces DCPIP, so a faster decolourisation shows more vitamin C. It is the standard test for ascorbic acid. Starch is tested with iodine and protein with the biuret reagent, and sodium chloride does not reduce DCPIP.', 3,
  'medicine/bio107', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio107' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
