insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'To avoid air bubbles when mounting a specimen, the cover slip should be',
  '[{"id": "a", "text": "dropped flat onto the specimen"}, {"id": "b", "text": "pressed down firmly with a finger"}, {"id": "c", "text": "lowered slowly at an angle, using a mounted needle"}, {"id": "d", "text": "placed before adding any liquid"}]'::jsonb, 'c', 'Lowering at an angle pushes the air out ahead of the water. Dropping it flat traps bubbles under the glass. Pressing down with a finger can break the slide and crush the specimen, and placing the cover slip before adding liquid traps air.', 2,
  'medicine/bio107', 'q009'
