select c.id, array['Logical']::text[], array['Procedural / supply chain']::text[], 'In an enzyme experiment, a tube containing boiled saliva is set up as a control. The boiled saliva shows that',
  '[{"id": "a", "text": "boiling makes saliva sweeter"}, {"id": "b", "text": "saliva has no enzymes"}, {"id": "c", "text": "temperature has no effect on enzymes"}, {"id": "d", "text": "any change seen in the other tubes is caused by active enzymes"}]'::jsonb, 'd', 'Boiling denatures the amylase, so if the control shows no change, the change elsewhere is due to active enzyme.', 3,
