insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Essential / definitive']::text[], 'In the Benedict''s test, a more intense brick-red colour and more precipitate suggest',
  '[{"id": "a", "text": "a higher concentration of reducing sugar"}, {"id": "b", "text": "a lower concentration of reducing sugar"}, {"id": "c", "text": "the presence of starch"}, {"id": "d", "text": "the presence of protein"}]'::jsonb, 'a', 'The amount of precipitate roughly follows the amount of reducing sugar, so the test is semi-quantitative. A lower concentration gives a paler green, yellow or orange result, and starch and protein do not react with Benedict''s reagent.', 3,
  'medicine/bio107', 'q017'
