insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'In paper chromatography of leaf pigments, a pigment travels 3.0 cm while the solvent front travels 6.0 cm. The Rf value of the pigment is',
  '[{"id": "a", "text": "2.0"}, {"id": "b", "text": "18"}, {"id": "c", "text": "3.0"}, {"id": "d", "text": "0.5"}]'::jsonb, 'd', 'Rf = distance moved by the pigment / distance moved by the solvent front = 3.0 / 6.0 = 0.5. The value 2.0 inverts the ratio and would be above 1, which is impossible.', 3,
  'medicine/bio107', 'q018'
from cgpa.courses c
