insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Procedural / supply chain']::text[], 'Before transferring bacteria with an inoculating loop, the loop should be',
  '[{"id": "a", "text": "dipped in tap water"}, {"id": "b", "text": "wiped with a dry cloth"}, {"id": "c", "text": "heated in a flame until red hot and then cooled"}, {"id": "d", "text": "used straight from the drawer"}]'::jsonb, 'c', 'Flaming sterilises the loop and prevents contamination of the culture. Letting it cool avoids killing the bacteria. Water does not sterilise, a dry cloth only removes visible dirt, and a loop straight from the drawer can carry contaminants.', 2,
  'medicine/bio107', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio107' and k.depot_qid = 'q019')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'In a Gram stain, Gram-positive bacteria appear',
  '[{"id": "a", "text": "pink, because they lose the crystal violet stain"}, {"id": "b", "text": "purple, because they retain the crystal violet stain"}, {"id": "c", "text": "colourless"}, {"id": "d", "text": "green"}]'::jsonb, 'b', 'A thick peptidoglycan wall retains the crystal violet. Gram-negative bacteria lose it and take up the pink safranin counterstain. A colourless cell would mean no counterstain was applied, which is not part of the standard method.', 3,
  'medicine/bio107', 'q020'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio107' and k.depot_qid = 'q020')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'An average of 4 plants were counted per 1 m^2 quadrat in a field of 500 m^2. The estimated number of plants in the field is',
  '[{"id": "a", "text": "2,000"}, {"id": "b", "text": "125"}, {"id": "c", "text": "500"}, {"id": "d", "text": "4"}]'::jsonb, 'a', 'Estimated total = mean per quadrat x (total area / quadrat area) = 4 x 500 = 2,000. The value 125 divides instead of multiplying.', 3,
  'medicine/bio108', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio108' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Procedural / supply chain']::text[], 'To avoid bias when placing quadrats in a field, a student should',
  '[{"id": "a", "text": "place them only where plants are plentiful"}, {"id": "b", "text": "place them in a straight line along the path"}, {"id": "c", "text": "avoid the edges and the centre"}, {"id": "d", "text": "choose positions using random coordinates"}]'::jsonb, 'd', 'Random placement gives each part of the field the same chance of being sampled. Choosing dense areas inflates the estimate. A line along a path, or avoiding the edges and centre, builds in a bias toward certain zones of the field.', 3,
  'medicine/bio108', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio108' and k.depot_qid = 'q002')
order by c.id limit 1;

