  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Procedural / supply chain']::text[], 'To study how species change from the seashore inland, a student should use a',
  '[{"id": "a", "text": "single random quadrat"}, {"id": "b", "text": "pitfall trap"}, {"id": "c", "text": "belt transect"}, {"id": "d", "text": "light trap"}]'::jsonb, 'c', 'A transect samples along a line with environmental change. A single quadrat cannot show a pattern along a gradient.', 3,
  'medicine/bio108', 'q003'
