order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'In a mark-recapture study, 40 animals were marked and released. A later sample of 50 contained 10 marked animals. The estimated population is',
  '[{"id": "a", "text": "80"}, {"id": "b", "text": "200"}, {"id": "c", "text": "20"}, {"id": "d", "text": "2,000"}]'::jsonb, 'b', 'N = (marked first x total second) / marked in second = 40 x 50 / 10 = 200. The value 80 treats the sample sizes as additive. The values 20 and 2,000 come from dividing or multiplying the wrong pair of numbers.', 4,
  'medicine/bio108', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio108' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Which soil type holds the most water?',
  '[{"id": "a", "text": "Sand"}, {"id": "b", "text": "Clay"}, {"id": "c", "text": "Gravel"}, {"id": "d", "text": "Coarse sandy loam"}]'::jsonb, 'b', 'Clay''s very small particles leave tiny pores that hold water. Sand drains quickly because its pores are large. Sand, gravel and coarse sandy loam all have large pores, so water drains through them.', 2,
  'medicine/bio108', 'q005'
from cgpa.courses c
