select c.id, array['Logical']::text[], array['Procedural / supply chain']::text[], 'A dichotomous key is used to',
  '[{"id": "a", "text": "identify organisms by choosing between pairs of contrasting statements"}, {"id": "b", "text": "count the population of an organism"}, {"id": "c", "text": "measure the pH of soil"}, {"id": "d", "text": "estimate the age of a tree"}]'::jsonb, 'a', 'Each step offers two options and leads to the next step or the name of the organism.', 2,
