  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio108' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Limewater turns milky when a gas from a respiring organism is bubbled through it. The gas is',
  '[{"id": "a", "text": "oxygen"}, {"id": "b", "text": "nitrogen"}, {"id": "c", "text": "hydrogen"}, {"id": "d", "text": "carbon dioxide"}]'::jsonb, 'd', 'Carbon dioxide reacts with calcium hydroxide to form insoluble calcium carbonate. This is why the limewater turns cloudy. Oxygen is used up in respiration, and nitrogen and hydrogen are not products of it. None of the three reacts with limewater.', 2,
  'medicine/bio108', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
