insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'A 3:1 ratio is expected among 80 offspring. The observed numbers are 66 dominant and 14 recessive. The chi-squared value is',
  '[{"id": "a", "text": "0.6"}, {"id": "b", "text": "1.8"}, {"id": "c", "text": "2.4"}, {"id": "d", "text": "36"}]'::jsonb, 'c', 'Expected: 60 and 20. Chi-squared = (66-60)^2/60 + (14-20)^2/20 = 0.6 + 1.8 = 2.4. The terms 0.6 and 1.8 are each only one part of the sum.', 5,
  'medicine/bio108', 'q014'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio108' and k.depot_qid = 'q014')
order by c.id limit 1;

