  '[{"id": "a", "text": "the difference is significant, so the hypothesis is rejected"}, {"id": "b", "text": "the difference from the expected ratio is not significant"}, {"id": "c", "text": "the experiment must be repeated until the value is above 3.84"}, {"id": "d", "text": "the offspring are not genetically related"}]'::jsonb, 'b', 'A value below the critical value is consistent with chance, so the 3:1 hypothesis is not rejected.', 4,
  'medicine/bio108', 'q015'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'bio108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/bio108' and k.depot_qid = 'q015')
