insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'What is the maximum number of electrons that the third shell (n = 3) can hold?',
  '[{"id": "a", "text": "8"}, {"id": "b", "text": "9"}, {"id": "c", "text": "32"}, {"id": "d", "text": "18"}]'::jsonb, 'd', 'The shell capacity is 2n squared, so 2 x 9 = 18. The value 8 is the octet that the outer shell often holds, and 32 is the capacity of the fourth shell. The value 9 is n squared and leaves out the factor of 2.', 2,
  'medicine/chem111', 'q002'
