select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Hund''s rule states that electrons',
  '[{"id": "a", "text": "cannot have the same set of four quantum numbers"}, {"id": "b", "text": "occupy orbitals of equal energy singly before pairing up"}, {"id": "c", "text": "fill the lowest energy orbitals first"}, {"id": "d", "text": "always pair in the s orbital"}]'::jsonb, 'b', 'Hund''s rule governs degenerate orbitals such as the three p orbitals. The statement about four quantum numbers is the Pauli exclusion principle, and the ''lowest first'' statement is the Aufbau principle.', 3,
  'medicine/chem111', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
