  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chem111' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Abstract / Visual']::text[], 'Which of these elements has the largest atomic radius?',
  '[{"id": "a", "text": "Magnesium"}, {"id": "b", "text": "Sodium"}, {"id": "c", "text": "Aluminium"}, {"id": "d", "text": "Chlorine"}]'::jsonb, 'b', 'Across a period the nuclear charge rises while shielding stays about the same, so radius falls. Sodium, at the start of period 3, is the largest of these. Chlorine sits at the far end of the period and has the smallest radius of the four, and magnesium and aluminium are both smaller than sodium.', 2,
  'medicine/chem111', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'chem111' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chem111' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Aluminium has a lower first ionisation energy than magnesium mainly because',
  '[{"id": "a", "text": "its outermost electron is in a higher-energy 3p orbital that is shielded by the 3s electrons"}, {"id": "b", "text": "aluminium has a smaller nuclear charge than magnesium"}, {"id": "c", "text": "aluminium has fewer protons than magnesium"}, {"id": "d", "text": "aluminium has a larger number of inner shells"}]'::jsonb, 'a', 'Aluminium''s 3p electron sits higher and is partly shielded, so it is easier to remove. Aluminium actually has MORE protons (13 against 12), so a smaller nuclear charge is the wrong reason.', 4,
  'medicine/chem111', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
