  '[{"id": "a", "text": "Oxygen"}, {"id": "b", "text": "Chlorine"}, {"id": "c", "text": "Nitrogen"}, {"id": "d", "text": "Fluorine"}]'::jsonb, 'd', 'Fluorine is the most electronegative element on the Pauling scale (about 4.0). Oxygen is next at about 3.5, which makes it the nearest wrong choice.', 2,
  'medicine/chem111', 'q007'
