insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Which compound shows predominantly ionic bonding?',
  '[{"id": "a", "text": "Methane"}, {"id": "b", "text": "Carbon dioxide"}, {"id": "c", "text": "Magnesium oxide"}, {"id": "d", "text": "Hydrogen chloride"}]'::jsonb, 'c', 'Magnesium oxide forms from a metal giving electrons to a non-metal. Hydrogen chloride is the nearest wrong choice, but it is a polar covalent molecule, because electrons are shared unequally rather than transferred.', 3,
  'medicine/chem111', 'q008'
from cgpa.courses c
