insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Abstract / Visual']::text[], 'The shape of the ammonia molecule, NH3, is',
  '[{"id": "a", "text": "tetrahedral"}, {"id": "b", "text": "trigonal planar"}, {"id": "c", "text": "trigonal pyramidal"}, {"id": "d", "text": "bent"}]'::jsonb, 'c', 'NH3 has three bonding pairs and one lone pair, giving a trigonal pyramidal shape. Tetrahedral describes the electron-pair arrangement, but the molecular shape excludes the lone pair.', 3,
  'medicine/chem111', 'q009'
