insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'What is the mass of 0.5 mol of calcium carbonate, CaCO3? (Ca = 40, C = 12, O = 16)',
  '[{"id": "a", "text": "100 g"}, {"id": "b", "text": "50 g"}, {"id": "c", "text": "25 g"}, {"id": "d", "text": "200 g"}]'::jsonb, 'b', 'Molar mass = 40 + 12 + 3(16) = 100 g/mol, so 0.5 mol has a mass of 50 g. The value 100 g is the mass of one whole mole. The value 25 g is the mass of 0.25 mol, and 200 g is the mass of 2 mol.', 2,
  'medicine/chem111', 'q010'
