insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'How many moles are in 22 g of carbon dioxide, CO2? (C = 12, O = 16)',
  '[{"id": "a", "text": "0.5 mol"}, {"id": "b", "text": "1.0 mol"}, {"id": "c", "text": "2.0 mol"}, {"id": "d", "text": "0.25 mol"}]'::jsonb, 'a', 'Molar mass = 12 + 32 = 44 g/mol, so moles = 22 / 44 = 0.5. Using 22 as the molar mass gives 1.0, which is the nearest wrong value.', 2,
