select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'How many molecules are present in 2 mol of a substance? (Avogadro constant = 6.02 x 10^23 per mol)',
  '[{"id": "a", "text": "6.02 x 10^23"}, {"id": "b", "text": "3.01 x 10^23"}, {"id": "c", "text": "1.20 x 10^23"}, {"id": "d", "text": "1.20 x 10^24"}]'::jsonb, 'd', 'Number = 2 x 6.02 x 10^23 = 1.204 x 10^24. The figure 6.02 x 10^23 is for only one mole.', 2,
  'medicine/chem111', 'q012'
