insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'Hydrogen burns in oxygen: 2H2 + O2 -> 2H2O. What mass of oxygen is needed to burn 4 g of hydrogen completely? (H = 1, O = 16)',
  '[{"id": "a", "text": "16 g"}, {"id": "b", "text": "64 g"}, {"id": "c", "text": "8 g"}, {"id": "d", "text": "32 g"}]'::jsonb, 'd', '4 g of H2 is 2 mol. The equation needs 1 mol of O2 for every 2 mol of H2, so 1 mol of O2 = 32 g. Using 16 g treats the oxygen as atoms instead of O2 molecules.', 3,
  'medicine/chem111', 'q013'
