insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'What is the percentage by mass of nitrogen in ammonium nitrate, NH4NO3? (H = 1, N = 14, O = 16)',
  '[{"id": "a", "text": "17.5%"}, {"id": "b", "text": "28%"}, {"id": "c", "text": "35%"}, {"id": "d", "text": "70%"}]'::jsonb, 'c', 'Molar mass = 28 + 4 + 48 = 80. Nitrogen contributes 2 x 14 = 28, so 28 / 80 = 35%. The value 17.5% counts only one nitrogen atom.', 4,
  'medicine/chem111', 'q014'
