insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A gas at 1 atm occupies 2 L. At constant temperature, it is compressed to 0.5 L. The new pressure is',
  '[{"id": "a", "text": "0.25 atm"}, {"id": "b", "text": "4 atm"}, {"id": "c", "text": "2 atm"}, {"id": "d", "text": "1 atm"}]'::jsonb, 'b', 'Boyle''s law gives P1V1 = P2V2, so 1 x 2 = P2 x 0.5 and P2 = 4 atm. The value 0.25 atm inverts the relationship. A pressure of 2 atm or 1 atm would mean the volume did not fall four-fold, and a smaller volume at constant temperature must raise the pressure.', 3,
  'medicine/chem111', 'q015'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'chem111' and c.approval_status = 'approved'
