insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], '50 cm3 of a 2 mol/dm3 solution is diluted to 200 cm3. The new concentration is',
  '[{"id": "a", "text": "0.25 mol/dm3"}, {"id": "b", "text": "1.0 mol/dm3"}, {"id": "c", "text": "8.0 mol/dm3"}, {"id": "d", "text": "0.5 mol/dm3"}]'::jsonb, 'd', 'C1V1 = C2V2, so 2 x 50 = C2 x 200 and C2 = 0.5. Diluting four-fold divides the concentration by four. Concentration cannot rise on dilution, which rules out 8.0 mol/dm3.', 3,
  'medicine/chem111', 'q018'
