insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'The oxidation number of manganese in potassium permanganate, KMnO4, is',
  '[{"id": "a", "text": "+2"}, {"id": "b", "text": "+4"}, {"id": "c", "text": "+7"}, {"id": "d", "text": "+6"}]'::jsonb, 'c', 'K is +1 and four O atoms are -8 in total, so Mn must be +7 to give a neutral compound. The value +6 is the figure for manganate, K2MnO4. The value +2 is the common manganese(II) state, and +4 is the state in MnO2.', 4,
  'medicine/chem122', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'chem122' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chem122' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'In the reaction Zn + Cu2+ -> Zn2+ + Cu, the oxidising agent is',
  '[{"id": "a", "text": "Zn"}, {"id": "b", "text": "Cu2+"}, {"id": "c", "text": "Zn2+"}, {"id": "d", "text": "Cu"}]'::jsonb, 'b', 'Cu2+ gains electrons and is reduced, so it is the oxidising agent. Zinc loses electrons and is the reducing agent. Zn2+ and Cu are the products, and neither takes up electrons in this reaction.', 3,
  'medicine/chem122', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'chem122' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chem122' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A current of 2.0 A flows for 965 s through copper(II) sulphate solution. What mass of copper is deposited? (Cu = 63.5; 1 F = 96,500 C/mol)',
  '[{"id": "a", "text": "0.635 g"}, {"id": "b", "text": "1.27 g"}, {"id": "c", "text": "0.3175 g"}, {"id": "d", "text": "6.35 g"}]'::jsonb, 'a', 'Charge = 2.0 x 965 = 1930 C = 0.02 mol of electrons. Cu2+ needs 2 electrons per atom, so 0.01 mol x 63.5 = 0.635 g. Ignoring the 2+ charge would give 1.27 g.', 5,
  'medicine/chem122', 'q011'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'chem122' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chem122' and k.depot_qid = 'q011')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Abstract / Visual']::text[], 'In a galvanic (voltaic) cell, oxidation takes place at the',
  '[{"id": "a", "text": "cathode, and electrons flow from it through the external circuit"}, {"id": "b", "text": "anode, and electrons flow through the salt bridge"}, {"id": "c", "text": "cathode, and electrons flow through the electrolyte"}, {"id": "d", "text": "anode, and electrons flow from it through the external circuit"}]'::jsonb, 'd', 'Oxidation always occurs at the anode. Electrons travel through the wire, while the salt bridge carries ions only.', 3,
  'medicine/chem122', 'q012'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'chem122' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chem122' and k.depot_qid = 'q012')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
