insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'The functional group present in ethanoic acid is the',
  '[{"id": "a", "text": "hydroxyl group, -OH"}, {"id": "b", "text": "carbonyl group, C=O only"}, {"id": "c", "text": "carboxyl group, -COOH"}, {"id": "d", "text": "amino group, -NH2"}]'::jsonb, 'c', 'Carboxylic acids contain -COOH. The hydroxyl group belongs to alcohols and is the nearest wrong choice because -OH is also part of the carboxyl group.', 2,
