insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Abstract / Visual']::text[], 'How many structural isomers does butane, C4H10, have (including butane itself)?',
  '[{"id": "a", "text": "1"}, {"id": "b", "text": "2"}, {"id": "c", "text": "3"}, {"id": "d", "text": "4"}]'::jsonb, 'b', 'The two are butane (straight chain) and 2-methylpropane (branched). Pentane, C5H12, is the alkane with three isomers. Four carbons can be arranged in only two ways, as a straight chain or with one methyl branch, so there is no third or fourth isomer.', 3,
  'medicine/chem122', 'q015'
