  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chem122' and k.depot_qid = 'q015')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Which type of reaction is characteristic of alkenes such as ethene?',
  '[{"id": "a", "text": "Addition"}, {"id": "b", "text": "Substitution"}, {"id": "c", "text": "Condensation"}, {"id": "d", "text": "Neutralisation"}]'::jsonb, 'a', 'The double bond opens and atoms add across it, for example when bromine water is decolourised. Substitution is the typical reaction of alkanes.', 2,
  'medicine/chem122', 'q016'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
