insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'Ethanol reacts with ethanoic acid in the presence of concentrated sulphuric acid to form',
  '[{"id": "a", "text": "ethyl ethanoate and water"}, {"id": "b", "text": "ethanal and hydrogen"}, {"id": "c", "text": "ethene and water"}, {"id": "d", "text": "sodium ethanoate and water"}]'::jsonb, 'a', 'This is esterification: an alcohol plus a carboxylic acid gives an ester and water. Sodium ethanoate would form only if sodium hydroxide were used.', 3,
  'medicine/chem122', 'q017'
