insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A reaction is spontaneous at a given temperature when its Gibbs free energy change, delta G, is',
  '[{"id": "a", "text": "positive"}, {"id": "b", "text": "equal to delta H"}, {"id": "c", "text": "equal to temperature"}, {"id": "d", "text": "negative"}]'::jsonb, 'd', 'Delta G = delta H - T delta S, and a negative value means the process can proceed spontaneously. A positive delta G means it is non-spontaneous in that direction.', 3,
  'medicine/chem122', 'q018'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'chem122' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chem122' and k.depot_qid = 'q018')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Which of these is a reducing sugar?',
  '[{"id": "a", "text": "Sucrose"}, {"id": "b", "text": "Starch"}, {"id": "c", "text": "Glucose"}, {"id": "d", "text": "Cellulose"}]'::jsonb, 'c', 'Glucose has a free aldehyde group in its open-chain form, so it reduces Benedict''s solution. Sucrose is the nearest wrong choice: its two units are joined through their reducing groups, so it does not reduce.', 3,
  'medicine/chem122', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
