  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chem122' and k.depot_qid = 'q019')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Mathematical Proofs']::text[], 'Hess''s law states that the enthalpy change of a reaction',
  '[{"id": "a", "text": "depends on the number of steps taken"}, {"id": "b", "text": "is the same whichever route is taken from reactants to products"}, {"id": "c", "text": "is always negative"}, {"id": "d", "text": "depends on the catalyst used"}]'::jsonb, 'b', 'Enthalpy is a state function, so only the initial and final states matter. A catalyst changes the route and the rate, but not the overall enthalpy change.', 3,
  'medicine/chem122', 'q020'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'chem122' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chem122' and k.depot_qid = 'q020')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'In a titration, a burette is read at the start as 0.50 cm^3 and at the end as 24.70 cm^3. The titre is',
  '[{"id": "a", "text": "24.20 cm^3"}, {"id": "b", "text": "25.20 cm^3"}, {"id": "c", "text": "24.70 cm^3"}, {"id": "d", "text": "23.20 cm^3"}]'::jsonb, 'a', 'Titre = final reading - initial reading = 24.70 - 0.50 = 24.20 cm^3. A burette scale increases downward, so the subtraction is final minus initial. The value 25.20 adds the starting reading, and 24.70 ignores it.', 2,
  'medicine/chm107', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'chm107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chm107' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'Before a titration, the burette should be rinsed with',
  '[{"id": "a", "text": "distilled water only"}, {"id": "b", "text": "the indicator"}, {"id": "c", "text": "the acid in the flask"}, {"id": "d", "text": "the solution it will contain"}]'::jsonb, 'd', 'Rinsing with the solution itself ensures that water left on the walls does not dilute it. The conical flask, by contrast, is rinsed with distilled water only.', 3,
  'medicine/chm107', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'chm107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chm107' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Procedural / supply chain']::text[], 'Which indicator is most suitable for titrating hydrochloric acid against aqueous ammonia (strong acid against weak base)?',
  '[{"id": "a", "text": "Phenolphthalein"}, {"id": "b", "text": "Litmus"}, {"id": "c", "text": "Methyl orange"}, {"id": "d", "text": "Universal indicator"}]'::jsonb, 'c', 'The equivalence point of this titration is acidic, and methyl orange changes colour over an acidic pH range. Phenolphthalein changes in a basic range, so its change would come after the true end point.', 4,
  'medicine/chm107', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
