insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Phenolphthalein is',
  '[{"id": "a", "text": "red in alkali and yellow in acid"}, {"id": "b", "text": "pink in alkaline solution and colourless in acid"}, {"id": "c", "text": "colourless in alkali and pink in acid"}, {"id": "d", "text": "yellow in alkali and red in acid"}]'::jsonb, 'b', 'Phenolphthalein turns pink above about pH 8.3. The red-in-acid, yellow-in-alkali pair describes methyl orange.', 2,
  'medicine/chm107', 'q005'
from cgpa.courses c
