insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], '25.0 cm^3 of 0.100 mol/dm^3 sodium hydroxide is neutralised by 20.0 cm^3 of hydrochloric acid. The concentration of the acid is',
  '[{"id": "a", "text": "0.125 mol/dm^3"}, {"id": "b", "text": "0.080 mol/dm^3"}, {"id": "c", "text": "0.100 mol/dm^3"}, {"id": "d", "text": "0.250 mol/dm^3"}]'::jsonb, 'a', 'Moles NaOH = 0.0250 x 0.100 = 0.00250. The acid reacts 1 : 1, so its concentration = 0.00250 / 0.0200 = 0.125 mol/dm^3. The value 0.080 inverts the ratio of volumes. The value 0.100 would hold only if the two volumes were equal, and since the acid volume is smaller, its concentration must be higher than 0.100.', 4,
  'medicine/chm107', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'chm107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chm107' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'What volume of 0.100 mol/dm^3 sodium hydroxide is needed to neutralise 20.0 cm^3 of 0.100 mol/dm^3 sulphuric acid?',
  '[{"id": "a", "text": "20.0 cm^3"}, {"id": "b", "text": "10.0 cm^3"}, {"id": "c", "text": "80.0 cm^3"}, {"id": "d", "text": "40.0 cm^3"}]'::jsonb, 'd', 'H2SO4 + 2NaOH -> Na2SO4 + 2H2O, so sulphuric acid needs twice as many moles of NaOH. Equal volumes would apply only to a 1 : 1 reaction.', 4,
  'medicine/chm107', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'chm107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/chm107' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Which substance is suitable as a primary standard for preparing a standard solution?',
  '[{"id": "a", "text": "Sodium hydroxide"}, {"id": "b", "text": "Concentrated hydrochloric acid"}, {"id": "c", "text": "Anhydrous sodium carbonate"}, {"id": "d", "text": "Potassium permanganate crystals"}]'::jsonb, 'c', 'A primary standard is pure, stable and not hygroscopic. Sodium hydroxide absorbs water and carbon dioxide from the air, so its mass is never exact.', 3,
  'medicine/chm107', 'q008'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
