insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Pale (white) infarcts typically occur in',
  '[{"id": "a", "text": "the lung and intestine"}, {"id": "b", "text": "the liver only"}, {"id": "c", "text": "solid organs with end-arterial circulation, such as the heart, spleen and kidney"}, {"id": "d", "text": "the brain only"}]'::jsonb, 'c', 'When there is no alternative blood supply, tissue dies and stays pale. Red infarcts occur in loose tissues with dual supply, such as the lung. The lung and intestine have a dual or collateral supply, so their infarcts are red. The brain, which liquefies, is not the only pale site.', 4,
