insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'In the PICO framework for a clinical research question, the letters stand for',
  '[{"id": "a", "text": "Population, Intervention, Comparison and Outcome"}, {"id": "b", "text": "Patient, Illness, Cause and Observation"}, {"id": "c", "text": "Prevalence, Incidence, Cohort and Odds"}, {"id": "d", "text": "Placebo, Intervention, Control and Output"}]'::jsonb, 'a', 'PICO structures a question so that the population, treatment, comparator and outcome are specified. It is widely used for searching literature. None of the other expansions is recognised, and PICO has no letter for illness, cohort or placebo.', 2,
  'medicine/mls406', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q001')
