insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A null hypothesis states that',
  '[{"id": "a", "text": "the treatment is always effective"}, {"id": "b", "text": "the sample is biased"}, {"id": "c", "text": "there is a strong correlation"}, {"id": "d", "text": "there is no difference or association between the variables being studied"}]'::jsonb, 'd', 'The null hypothesis is the default that a test attempts to reject. The researcher''s expected effect is stated in the alternative hypothesis. A treatment that always works, a biased sample and a strong correlation are claims of effect or of a flaw, not the statement of no difference.', 2,
  'medicine/mls406', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'In a study of the effect of a drug dose on blood pressure, the dependent variable is',
  '[{"id": "a", "text": "the drug dose"}, {"id": "b", "text": "the age of the investigator"}, {"id": "c", "text": "blood pressure"}, {"id": "d", "text": "the sample size"}]'::jsonb, 'c', 'The dependent variable is the outcome measured. The dose, which the researcher manipulates, is the independent variable. The drug dose is the independent variable, and the investigator''s age and the sample size are not outcomes of the dose.', 2,
  'medicine/mls406', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q003')
order by c.id limit 1;

