select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A cohort study is characterised by',
  '[{"id": "a", "text": "comparing people with and without disease by looking back at past exposure"}, {"id": "b", "text": "following exposed and unexposed groups over time to compare the incidence of disease"}, {"id": "c", "text": "measuring exposure and disease at a single point in time"}, {"id": "d", "text": "randomly allocating participants to treatments"}]'::jsonb, 'b', 'Cohort studies give incidence and relative risk. The looking-back description fits a case-control study.', 3,
