select c.id, array['Statistical / Predictive']::text[], array['Contextual / rhetoric']::text[], 'A researcher interviews only the patients who happen to attend the clinic on a Monday. This sample is vulnerable to',
  '[{"id": "a", "text": "recall bias only"}, {"id": "b", "text": "selection bias, limiting generalisability"}, {"id": "c", "text": "measurement error in the instrument only"}, {"id": "d", "text": "confounding only"}]'::jsonb, 'b', 'Convenience samples may differ from the target population. People attending on one day need not represent all patients.', 3,
  'medicine/mls406', 'q010'
