insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'In a study of coffee drinking and lung cancer, smoking is a confounder because it',
  '[{"id": "a", "text": "is associated with both coffee drinking and lung cancer"}, {"id": "b", "text": "is the outcome of the study"}, {"id": "c", "text": "lies on the causal path from coffee to cancer"}, {"id": "d", "text": "is unrelated to either"}]'::jsonb, 'a', 'A confounder is linked to both the exposure and the outcome, and can create a false association. Randomisation, restriction or adjustment can control it.', 4,
  'medicine/mls406', 'q011'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
