insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'In a double-blind trial,',
  '[{"id": "a", "text": "only the participants know the allocation"}, {"id": "b", "text": "only the statistician knows the allocation"}, {"id": "c", "text": "everyone knows the allocation"}, {"id": "d", "text": "neither the participants nor the investigators know who receives the treatment"}]'::jsonb, 'd', 'Blinding reduces observer and participant bias. Single-blind trials hide the allocation from only one party.', 3,
  'medicine/mls406', 'q012'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q012')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A weighing scale always reads 2 kg too high but gives the same value on repeated weighing. The scale is',
  '[{"id": "a", "text": "valid but not reliable"}, {"id": "b", "text": "neither reliable nor valid"}, {"id": "c", "text": "both reliable and valid"}, {"id": "d", "text": "reliable but not valid"}]'::jsonb, 'd', 'Reliability is consistency, and the scale is consistent. Validity is accuracy about what is being measured, and the constant error means the readings are wrong.', 4,
  'medicine/mls406', 'q013'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q013')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'Which document, issued by the World Medical Association, sets out ethical principles for medical research on human subjects?',
  '[{"id": "a", "text": "The Hippocratic Oath"}, {"id": "b", "text": "The Geneva Convention"}, {"id": "c", "text": "The Declaration of Helsinki"}, {"id": "d", "text": "The Beveridge Report"}]'::jsonb, 'c', 'The Declaration of Helsinki, first adopted in 1964, emphasises consent and independent ethical review. The Nuremberg Code, the earlier document, arose from the trials of Nazi doctors. The Hippocratic Oath is a general medical pledge, the Geneva Convention concerns war, and the Beveridge Report is a British social welfare plan.', 3,
  'medicine/mls406', 'q014'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q014')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Procedural / supply chain']::text[], 'In research involving human participants, ethical approval should be obtained',
  '[{"id": "a", "text": "after the data are analysed"}, {"id": "b", "text": "before data collection begins"}, {"id": "c", "text": "only if the study is published"}, {"id": "d", "text": "only if there is a risk of death"}]'::jsonb, 'b', 'Approval before the study starts protects participants. Seeking it afterwards means that people may already have been exposed to risk.', 2,
  'medicine/mls406', 'q015'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q015')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Contextual / rhetoric']::text[], 'Informed consent requires that the participant',
  '[{"id": "a", "text": "receives the information about the study and agrees voluntarily"}, {"id": "b", "text": "signs a form without reading it"}, {"id": "c", "text": "is told that refusal will affect their treatment"}, {"id": "d", "text": "is paid enough that they cannot decline"}]'::jsonb, 'a', 'Consent must be informed and free from coercion. Pressure, whether threats or large payments, undermines voluntariness. Signing without reading removes the information, and threats to treatment or an irresistible payment remove free choice.', 3,
  'medicine/mls406', 'q016'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q016')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Procedural / supply chain']::text[], 'Which referencing style numbers references in the order they are first cited and is widely used in medical journals?',
  '[{"id": "a", "text": "Vancouver"}, {"id": "b", "text": "Harvard"}, {"id": "c", "text": "MLA"}, {"id": "d", "text": "Chicago author-date"}]'::jsonb, 'a', 'The Vancouver style uses numbers in the text that match a numbered list. Harvard uses the author''s name and year.', 2,
  'medicine/mls406', 'q017'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
