  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q017')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'The sections of a typical scientific research article follow the IMRaD structure, which stands for',
  '[{"id": "a", "text": "Introduction, Measurement, Review and Data"}, {"id": "b", "text": "Information, Method, Reference and Design"}, {"id": "c", "text": "Idea, Material, Research and Decision"}, {"id": "d", "text": "Introduction, Methods, Results and Discussion"}]'::jsonb, 'd', 'IMRaD gives readers a standard order: why the study was done, how, what was found, and what it means. The other three phrases are not expansions of IMRaD.', 2,
  'medicine/mls406', 'q018'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q018')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Contextual / rhetoric']::text[], 'The question ''Do you find the lecturer clear and punctual?'' is a poor questionnaire item because it is',
  '[{"id": "a", "text": "too short"}, {"id": "b", "text": "an open question"}, {"id": "c", "text": "double-barrelled, asking about two things at once"}, {"id": "d", "text": "too easy to answer"}]'::jsonb, 'c', 'A respondent who finds the lecturer clear but late cannot give a single honest answer. Each item should ask about one issue only.', 3,
  'medicine/mls406', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q019')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'A pilot study is conducted in order to',
  '[{"id": "a", "text": "replace the main study"}, {"id": "b", "text": "test the feasibility of the study procedures and instruments on a small scale"}, {"id": "c", "text": "prove the hypothesis conclusively"}, {"id": "d", "text": "avoid ethical approval"}]'::jsonb, 'b', 'Problems with questions, logistics or sample size estimates can be corrected before the main study. A pilot does not replace the main study because its sample is too small.', 3,
  'medicine/mls406', 'q020'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'mls406' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/mls406' and k.depot_qid = 'q020')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Pharmacokinetics is the study of',
  '[{"id": "a", "text": "what the body does to a drug: absorption, distribution, metabolism and excretion"}, {"id": "b", "text": "what a drug does to the body"}, {"id": "c", "text": "the chemical synthesis of drugs"}, {"id": "d", "text": "the side effects of drugs only"}]'::jsonb, 'a', 'Pharmacokinetics follows the drug through the body (ADME). The effect of the drug on the body is pharmacodynamics, which is the nearest wrong choice.', 2,
  'medicine/pco320', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'The bioavailability of a drug given intravenously is',
  '[{"id": "a", "text": "50%"}, {"id": "b", "text": "about 80%"}, {"id": "c", "text": "zero"}, {"id": "d", "text": "100%"}]'::jsonb, 'd', 'The whole dose enters the systemic circulation directly. Oral drugs are lower because of incomplete absorption and first-pass metabolism. Other routes lose part of the dose to absorption or first-pass metabolism, and a bioavailability of zero is impossible for a drug that works.', 2,
  'medicine/pco320', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'First-pass metabolism reduces the bioavailability of an oral drug because the drug',
  '[{"id": "a", "text": "is destroyed by saliva"}, {"id": "b", "text": "is excreted unchanged in the bile only"}, {"id": "c", "text": "passes through the liver via the portal vein before reaching the systemic circulation"}, {"id": "d", "text": "cannot cross the gut wall"}]'::jsonb, 'c', 'Portal blood goes to the liver first, so part of the dose is metabolised before reaching the body. Sublingual glyceryl trinitrate avoids this effect. Saliva does not destroy most oral drugs, and a drug that crosses the gut wall is the one that reaches the portal blood.', 3,
  'medicine/pco320', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Aspirin is a weak acid (pKa about 3.5). In the acidic stomach (pH 2) it is mainly',
  '[{"id": "a", "text": "ionised, which favours absorption"}, {"id": "b", "text": "un-ionised, which favours absorption"}, {"id": "c", "text": "ionised and not absorbable at all"}, {"id": "d", "text": "destroyed by the acid"}]'::jsonb, 'b', 'A weak acid is mostly un-ionised when the pH is below its pKa. The un-ionised form is lipid-soluble and crosses membranes more easily. At pH 2 aspirin is not mostly ionised, and the ionised form is the one that is poorly absorbed, so ''ionised and absorbed'' is backward.', 4,
  'medicine/pco320', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A drug has an elimination rate constant of 0.1 per hour. Using t1/2 = 0.693 / k, its half-life is about',
  '[{"id": "a", "text": "0.07 hours"}, {"id": "b", "text": "6.9 hours"}, {"id": "c", "text": "10 hours"}, {"id": "d", "text": "69 hours"}]'::jsonb, 'b', 't1/2 = 0.693 / 0.1 = 6.93 hours. Taking the reciprocal of k, 10 hours, forgets the constant 0.693. Multiplying 0.693 by k gives 0.07 hours, which turns the formula upside down.', 3,
  'medicine/pco320', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A drug with a half-life of 6 hours, given repeatedly, reaches steady-state plasma concentration after about',
  '[{"id": "a", "text": "24 to 30 hours"}, {"id": "b", "text": "6 hours"}, {"id": "c", "text": "12 hours"}, {"id": "d", "text": "3 days"}]'::jsonb, 'a', 'Steady state needs about 4 to 5 half-lives, which is 24 to 30 hours here. After one half-life, the drug is only half-way to steady state.', 3,
  'medicine/pco320', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], '500 mg of a drug is given intravenously and the initial plasma concentration is 10 mg/L. The volume of distribution is',
  '[{"id": "a", "text": "5,000 L"}, {"id": "b", "text": "0.02 L"}, {"id": "c", "text": "510 L"}, {"id": "d", "text": "50 L"}]'::jsonb, 'd', 'Vd = dose / concentration = 500 / 10 = 50 L. The figure is an apparent volume and may exceed the body''s real fluid volume. The value 5,000 L multiplies dose and concentration, 0.02 L inverts the ratio, and 510 L adds the two.', 3,
  'medicine/pco320', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A drug has k = 0.1 per hour and a volume of distribution of 50 L. Its clearance is',
  '[{"id": "a", "text": "500 L per hour"}, {"id": "b", "text": "0.002 L per hour"}, {"id": "c", "text": "5 L per hour"}, {"id": "d", "text": "50 L per hour"}]'::jsonb, 'c', 'CL = k x Vd = 0.1 x 50 = 5 L/h. Using Vd alone as the clearance confuses volume with rate.', 4,
  'medicine/pco320', 'q008'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q008')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A loading dose is required to reach a target plasma concentration of 4 mg/L in a patient with Vd = 50 L and bioavailability 1. The dose is',
  '[{"id": "a", "text": "12.5 mg"}, {"id": "b", "text": "54 mg"}, {"id": "c", "text": "200 mg"}, {"id": "d", "text": "2,000 mg"}]'::jsonb, 'c', 'Loading dose = target concentration x Vd / F = 4 x 50 / 1 = 200 mg. Dividing instead of multiplying gives 12.5 mg.', 4,
  'medicine/pco320', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Which drug shows zero-order (saturation) kinetics at high doses?',
  '[{"id": "a", "text": "Penicillin"}, {"id": "b", "text": "Phenytoin"}, {"id": "c", "text": "Atenolol"}, {"id": "d", "text": "Paracetamol at normal doses"}]'::jsonb, 'b', 'Phenytoin''s metabolising enzymes saturate, so a constant amount is cleared per hour, and small dose increases cause large rises in plasma level. Alcohol behaves similarly. Penicillin and atenolol are cleared by first-order processes, and so is paracetamol at normal doses.', 4,
  'medicine/pco320', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Rifampicin, a CYP450 enzyme inducer, given with warfarin will',
  '[{"id": "a", "text": "reduce the anticoagulant effect of warfarin"}, {"id": "b", "text": "increase the anticoagulant effect of warfarin"}, {"id": "c", "text": "have no effect on warfarin"}, {"id": "d", "text": "make warfarin work faster at the same dose"}]'::jsonb, 'a', 'Induction speeds up metabolism of warfarin, so its level falls and clotting risk rises. An enzyme inhibitor would have the opposite effect.', 4,
  'medicine/pco320', 'q011'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q011')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Abstract / Visual']::text[], 'A competitive antagonist shifts the dose-response curve of an agonist',
  '[{"id": "a", "text": "to the left, with a higher maximum"}, {"id": "b", "text": "downwards, with a lower maximum and no shift"}, {"id": "c", "text": "not at all"}, {"id": "d", "text": "to the right, with no change in the maximum response"}]'::jsonb, 'd', 'Increasing the agonist dose can overcome a competitive antagonist, so the curve shifts right but still reaches the same maximum. A non-competitive antagonist lowers the maximum.', 4,
  'medicine/pco320', 'q012'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q012')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'The therapeutic index of a drug with an LD50 of 200 mg/kg and an ED50 of 10 mg/kg is',
  '[{"id": "a", "text": "0.05"}, {"id": "b", "text": "210"}, {"id": "c", "text": "190"}, {"id": "d", "text": "20"}]'::jsonb, 'd', 'Therapeutic index = LD50 / ED50 = 200 / 10 = 20. A larger index indicates a wider safety margin. The value 0.05 inverts the ratio, and 210 and 190 add and subtract the two doses.', 3,
  'medicine/pco320', 'q013'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q013')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A drug that produces the greater maximum response is said to have the greater',
  '[{"id": "a", "text": "potency"}, {"id": "b", "text": "bioavailability"}, {"id": "c", "text": "efficacy"}, {"id": "d", "text": "clearance"}]'::jsonb, 'c', 'Efficacy is the maximum effect a drug can produce. Potency is the dose needed for a given effect, which is the nearest wrong choice.', 3,
  'medicine/pco320', 'q014'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q014')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'A rapidly developing reduction in response to a drug on repeated dosing within a short time is called',
  '[{"id": "a", "text": "idiosyncrasy"}, {"id": "b", "text": "tachyphylaxis"}, {"id": "c", "text": "synergism"}, {"id": "d", "text": "hypersensitivity"}]'::jsonb, 'b', 'Tachyphylaxis occurs within minutes to hours. Tolerance, by comparison, develops more gradually with repeated use. Idiosyncrasy is an unusual, genetically determined reaction, synergism is a combined effect larger than the sum of the parts, and hypersensitivity is an immune reaction. None describes a rapid fall in response.', 3,
  'medicine/pco320', 'q015'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q015')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'A Type A adverse drug reaction is',
  '[{"id": "a", "text": "dose-related and predictable from the drug''s pharmacology"}, {"id": "b", "text": "unpredictable and not dose-related"}, {"id": "c", "text": "always allergic in nature"}, {"id": "d", "text": "seen only in children"}]'::jsonb, 'a', 'Type A reactions are extensions of the known action, such as hypoglycaemia with insulin. Type B reactions, such as penicillin anaphylaxis, are unpredictable.', 3,
  'medicine/pco320', 'q016'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q016')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Phase II drug metabolism usually involves',
  '[{"id": "a", "text": "conjugation, such as glucuronidation, which makes the drug more water-soluble"}, {"id": "b", "text": "oxidation by CYP450 only"}, {"id": "c", "text": "binding to plasma albumin"}, {"id": "d", "text": "excretion through the lungs"}]'::jsonb, 'a', 'Conjugation attaches polar groups to aid renal or biliary excretion. Oxidation by CYP450 is Phase I metabolism.', 4,
  'medicine/pco320', 'q017'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q017')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Which route of administration gives the fastest onset of action?',
  '[{"id": "a", "text": "Oral"}, {"id": "b", "text": "Intramuscular"}, {"id": "c", "text": "Transdermal"}, {"id": "d", "text": "Intravenous"}]'::jsonb, 'd', 'Intravenous injection delivers the drug directly into the blood. The intramuscular route is nearer but still requires absorption from the muscle.', 2,
