insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Essential / definitive']::text[], 'The nicotinic acetylcholine receptor is an example of a',
  '[{"id": "a", "text": "G protein-coupled receptor"}, {"id": "b", "text": "nuclear receptor"}, {"id": "c", "text": "ligand-gated ion channel"}, {"id": "d", "text": "enzyme-linked receptor"}]'::jsonb, 'c', 'Binding of acetylcholine opens the channel within milliseconds. G protein-coupled receptors, such as muscarinic receptors, respond more slowly.', 3,
  'medicine/pco320', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
