insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'In aspirin overdose, alkalinising the urine with sodium bicarbonate increases excretion because aspirin is',
  '[{"id": "a", "text": "a weak base, which becomes more ionised"}, {"id": "b", "text": "a weak acid, which becomes more ionised and is trapped in alkaline urine"}, {"id": "c", "text": "a strong acid that is always excreted"}, {"id": "d", "text": "metabolised faster in alkaline urine"}]'::jsonb, 'b', 'Ionised molecules are not reabsorbed across the renal tubule, so more drug is eliminated. This is ion trapping.', 5,
  'medicine/pco320', 'q020'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco320' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco320' and k.depot_qid = 'q020')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Atropine produces its effects by',
  '[{"id": "a", "text": "competitively blocking muscarinic acetylcholine receptors"}, {"id": "b", "text": "blocking nicotinic receptors at the neuromuscular junction"}, {"id": "c", "text": "inhibiting acetylcholinesterase"}, {"id": "d", "text": "stimulating beta-adrenergic receptors"}]'::jsonb, 'a', 'Blocking muscarinic receptors causes dry mouth, dilated pupils and tachycardia. Inhibiting acetylcholinesterase, by contrast, raises acetylcholine and produces the opposite effects.', 2,
  'medicine/pco421', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Neostigmine is useful in myasthenia gravis because it',
  '[{"id": "a", "text": "blocks muscarinic receptors"}, {"id": "b", "text": "stimulates alpha receptors"}, {"id": "c", "text": "blocks calcium channels"}, {"id": "d", "text": "inhibits acetylcholinesterase, increasing acetylcholine at the neuromuscular junction"}]'::jsonb, 'd', 'More acetylcholine remains to stimulate the weakened receptors, improving muscle strength.', 3,
  'medicine/pco421', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
