insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Salbutamol relieves asthma by',
  '[{"id": "a", "text": "blocking beta-1 receptors"}, {"id": "b", "text": "blocking muscarinic receptors in the heart"}, {"id": "c", "text": "stimulating beta-2 adrenergic receptors, causing bronchodilation"}, {"id": "d", "text": "inhibiting leukotriene synthesis"}]'::jsonb, 'c', 'Beta-2 stimulation relaxes bronchial smooth muscle. Tremor and tachycardia are common side effects. Blocking beta-1 receptors slows the heart rather than opening the airways, and leukotriene inhibition is the action of montelukast.', 2,
  'medicine/pco421', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Propranolol should be avoided in asthma because it',
  '[{"id": "a", "text": "is a beta-2 agonist that overstimulates the bronchi"}, {"id": "b", "text": "is a non-selective beta blocker that can cause bronchospasm"}, {"id": "c", "text": "blocks muscarinic receptors"}, {"id": "d", "text": "raises blood pressure"}]'::jsonb, 'b', 'Blocking beta-2 receptors in the airways can provoke an attack. A cardioselective agent is safer, but is still used with caution.', 3,
  'medicine/pco421', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'The first-line drug for anaphylaxis is',
  '[{"id": "a", "text": "intravenous antihistamine alone"}, {"id": "b", "text": "adrenaline given intramuscularly"}, {"id": "c", "text": "oral prednisolone"}, {"id": "d", "text": "intravenous atropine"}]'::jsonb, 'b', 'Adrenaline reverses bronchospasm, vasodilation and oedema quickly. Antihistamines and steroids are adjuncts, which are too slow to be the first treatment. Atropine has no role in reversing anaphylaxis.', 3,
  'medicine/pco421', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A dry persistent cough is a recognised side effect of',
  '[{"id": "a", "text": "enalapril, an ACE inhibitor, due to accumulation of bradykinin"}, {"id": "b", "text": "amlodipine, due to blockade of calcium channels"}, {"id": "c", "text": "losartan, due to blockade of AT1 receptors"}, {"id": "d", "text": "furosemide, due to loss of potassium"}]'::jsonb, 'a', 'ACE also breaks down bradykinin, so inhibiting it causes bradykinin to build up. Losartan does not do this, which is why it is used when cough occurs.', 3,
  'medicine/pco421', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q006')
