insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'The antidote for heparin overdose is',
  '[{"id": "a", "text": "vitamin K"}, {"id": "b", "text": "naloxone"}, {"id": "c", "text": "flumazenil"}, {"id": "d", "text": "protamine sulphate"}]'::jsonb, 'd', 'Protamine binds heparin and neutralises it. Vitamin K reverses warfarin and is slower, which is why it is the nearest wrong choice.', 3,
  'medicine/pco421', 'q013'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q013')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Aspirin has an antiplatelet effect because it',
  '[{"id": "a", "text": "blocks vitamin K epoxide reductase"}, {"id": "b", "text": "activates antithrombin"}, {"id": "c", "text": "irreversibly inhibits cyclooxygenase-1, reducing thromboxane A2"}, {"id": "d", "text": "dissolves fibrin"}]'::jsonb, 'c', 'Platelets cannot make new enzyme, so the inhibition lasts for the life of the platelet. Warfarin, not aspirin, acts on vitamin K.', 4,
  'medicine/pco421', 'q014'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q014')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'Naloxone is used to treat',
  '[{"id": "a", "text": "benzodiazepine overdose"}, {"id": "b", "text": "opioid overdose with respiratory depression and pinpoint pupils"}, {"id": "c", "text": "paracetamol overdose"}, {"id": "d", "text": "organophosphate poisoning"}]'::jsonb, 'b', 'Naloxone is a competitive opioid antagonist. Flumazenil is the antagonist for benzodiazepines. Paracetamol overdose is treated with acetylcysteine, and organophosphate poisoning with atropine and pralidoxime.', 3,
  'medicine/pco421', 'q015'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
