  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q015')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Carbamazepine controls focal seizures mainly by',
  '[{"id": "a", "text": "blocking voltage-gated sodium channels"}, {"id": "b", "text": "enhancing GABA release by blocking calcium channels"}, {"id": "c", "text": "inhibiting the enzyme carbonic anhydrase"}, {"id": "d", "text": "blocking NMDA receptors only"}]'::jsonb, 'a', 'It stabilises neuronal membranes by prolonging the inactive state of sodium channels, so repetitive firing is reduced. Blocking calcium channels is the action of ethosuximide, and carbonic anhydrase is the target of acetazolamide.', 4,
  'medicine/pco421', 'q016'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q016')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Metformin lowers blood glucose mainly by',
  '[{"id": "a", "text": "reducing hepatic gluconeogenesis and improving insulin sensitivity"}, {"id": "b", "text": "stimulating insulin release from beta cells"}, {"id": "c", "text": "blocking intestinal lipase"}, {"id": "d", "text": "increasing urinary excretion of glucose"}]'::jsonb, 'a', 'It does not stimulate insulin secretion, so on its own it seldom causes hypoglycaemia. Sulfonylureas, the nearest wrong choice, stimulate insulin release.', 4,
  'medicine/pco421', 'q017'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q017')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Digoxin increases the force of cardiac contraction by',
  '[{"id": "a", "text": "blocking calcium channels"}, {"id": "b", "text": "blocking beta-1 receptors"}, {"id": "c", "text": "opening potassium channels"}, {"id": "d", "text": "inhibiting the Na+/K+ ATPase pump, raising intracellular calcium"}]'::jsonb, 'd', 'Higher intracellular sodium reduces calcium removal, so contractions strengthen. Hypokalaemia increases the risk of digoxin toxicity. Blocking calcium channels, blocking beta-1 receptors and opening potassium channels are the actions of other drugs, and none of them raises intracellular calcium.', 4,
  'medicine/pco421', 'q018'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q018')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Statins, such as simvastatin, lower cholesterol by inhibiting',
  '[{"id": "a", "text": "lipoprotein lipase"}, {"id": "b", "text": "pancreatic lipase"}, {"id": "c", "text": "HMG-CoA reductase"}, {"id": "d", "text": "cyclooxygenase"}]'::jsonb, 'c', 'This blocks an early step in hepatic cholesterol synthesis. A well-known adverse effect is myopathy. Lipoprotein lipase is activated by fibrates, pancreatic lipase is inhibited by orlistat, and cyclooxygenase is inhibited by aspirin.', 3,
  'medicine/pco421', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco421' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q019')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Omeprazole reduces gastric acid by',
  '[{"id": "a", "text": "blocking histamine H2 receptors"}, {"id": "b", "text": "irreversibly inhibiting the H+/K+ ATPase (proton pump) of parietal cells"}, {"id": "c", "text": "neutralising stomach acid directly"}, {"id": "d", "text": "blocking muscarinic receptors"}]'::jsonb, 'b', 'The proton pump is the final step of acid secretion. H2 blockers such as ranitidine are the nearest wrong choice, as they act earlier in the pathway.', 3,
  'medicine/pco421', 'q020'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
