  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco421' and k.depot_qid = 'q020')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Penicillins kill bacteria by',
  '[{"id": "a", "text": "inhibiting cell wall synthesis through binding to penicillin-binding proteins"}, {"id": "b", "text": "inhibiting protein synthesis at the 30S subunit"}, {"id": "c", "text": "inhibiting DNA gyrase"}, {"id": "d", "text": "blocking folic acid synthesis"}]'::jsonb, 'a', 'Beta-lactams block cross-linking of peptidoglycan, so the wall is weak and the cell lyses. Protein synthesis inhibition describes aminoglycosides and tetracyclines.', 3,
  'medicine/pco441', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
