  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco441' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Clavulanic acid is combined with amoxicillin to',
  '[{"id": "a", "text": "increase renal excretion of amoxicillin"}, {"id": "b", "text": "kill anaerobic bacteria directly"}, {"id": "c", "text": "block protein synthesis"}, {"id": "d", "text": "inhibit beta-lactamase enzymes that destroy amoxicillin"}]'::jsonb, 'd', 'It protects the beta-lactam ring from bacterial enzymes, so resistant organisms become susceptible. Clavulanic acid has little antibacterial action of its own, so it neither kills anaerobes directly nor blocks protein synthesis, and faster excretion would lower the amoxicillin level.', 3,
  'medicine/pco441', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco441' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco441' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Methicillin-resistant Staphylococcus aureus (MRSA) is resistant because of',
  '[{"id": "a", "text": "production of ethambutol"}, {"id": "b", "text": "loss of the cell membrane"}, {"id": "c", "text": "the mecA gene producing an altered penicillin-binding protein (PBP2a)"}, {"id": "d", "text": "a plasmid for vitamin K"}]'::jsonb, 'c', 'PBP2a has a low affinity for beta-lactams, so these drugs cannot block cell wall synthesis. A simple beta-lactamase does not explain MRSA.', 4,
  'medicine/pco441', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco441' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco441' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Gentamicin, an aminoglycoside, acts by binding to the',
  '[{"id": "a", "text": "50S ribosomal subunit and causes grey baby syndrome"}, {"id": "b", "text": "30S ribosomal subunit and is associated with nephrotoxicity and ototoxicity"}, {"id": "c", "text": "DNA gyrase and causes tendon rupture"}, {"id": "d", "text": "RNA polymerase and colours urine orange"}]'::jsonb, 'b', 'Aminoglycosides cause misreading of mRNA and are bactericidal. Their serious toxicity affects the kidney and the eighth cranial nerve. Grey baby syndrome is caused by chloramphenicol, tendon rupture by fluoroquinolones, and orange urine by rifampicin.', 4,
  'medicine/pco441', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco441' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco441' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Tetracyclines should be avoided in pregnancy and in children under 8 years because they',
  '[{"id": "a", "text": "cause deafness in the fetus"}, {"id": "b", "text": "deposit in developing bones and teeth, causing staining and impaired growth"}, {"id": "c", "text": "cause grey baby syndrome"}, {"id": "d", "text": "cause hepatic failure in every patient"}]'::jsonb, 'b', 'They chelate calcium in growing tissue and discolour teeth permanently. Grey baby syndrome is a toxicity of chloramphenicol.', 3,
  'medicine/pco441', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco441' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco441' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Ciprofloxacin acts by inhibiting',
  '[{"id": "a", "text": "bacterial DNA gyrase (topoisomerase II) and topoisomerase IV"}, {"id": "b", "text": "bacterial RNA polymerase"}, {"id": "c", "text": "dihydrofolate reductase"}, {"id": "d", "text": "cell wall synthesis"}]'::jsonb, 'a', 'Blocking DNA supercoiling prevents replication. A recognised adverse effect is tendon damage, especially in older patients. RNA polymerase is the target of rifampicin, dihydrofolate reductase of trimethoprim, and cell wall synthesis of the beta-lactams.', 3,
  'medicine/pco441', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco441' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco441' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Rifampicin acts by inhibiting',
  '[{"id": "a", "text": "mycolic acid synthesis"}, {"id": "b", "text": "arabinosyl transferase"}, {"id": "c", "text": "the 30S ribosomal subunit"}, {"id": "d", "text": "bacterial DNA-dependent RNA polymerase"}]'::jsonb, 'd', 'It stops transcription. It also colours urine and tears orange-red, and induces liver enzymes. Mycolic acid synthesis is the target of isoniazid.', 3,
  'medicine/pco441', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
