  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco441' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Procedural / supply chain']::text[], 'The standard first-line regimen for drug-susceptible tuberculosis is',
  '[{"id": "a", "text": "2 weeks of rifampicin alone"}, {"id": "b", "text": "12 months of isoniazid alone"}, {"id": "c", "text": "2 months of isoniazid, rifampicin, pyrazinamide and ethambutol, followed by 4 months of isoniazid and rifampicin"}, {"id": "d", "text": "1 month of ciprofloxacin and ethambutol"}]'::jsonb, 'c', 'Combination therapy prevents drug resistance, and the intensive phase kills most bacilli quickly. Single-drug treatment would select resistant organisms.', 4,
  'medicine/pco441', 'q008'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
