  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco441' and k.depot_qid = 'q008')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Peripheral neuropathy caused by isoniazid is prevented by giving',
  '[{"id": "a", "text": "vitamin C"}, {"id": "b", "text": "vitamin K"}, {"id": "c", "text": "pyridoxine (vitamin B6)"}, {"id": "d", "text": "folic acid"}]'::jsonb, 'c', 'Isoniazid depletes pyridoxine, and supplementation prevents the neuropathy. Vitamin K is used for warfarin reversal, which is unrelated. Vitamin C, vitamin K and folic acid do not replace the pyridoxine that isoniazid depletes.', 3,
  'medicine/pco441', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
