insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Optic neuritis, which can cause loss of colour vision, is the characteristic toxicity of',
  '[{"id": "a", "text": "rifampicin"}, {"id": "b", "text": "ethambutol"}, {"id": "c", "text": "pyrazinamide"}, {"id": "d", "text": "isoniazid"}]'::jsonb, 'b', 'Patients on ethambutol should have their vision checked. Pyrazinamide''s typical toxicities are hepatotoxicity and hyperuricaemia.', 4,
  'medicine/pco441', 'q010'
from cgpa.courses c
