order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Co-trimoxazole combines sulfamethoxazole and trimethoprim, which act by',
  '[{"id": "a", "text": "blocking two sequential steps in bacterial folate synthesis"}, {"id": "b", "text": "blocking two steps in protein synthesis"}, {"id": "c", "text": "damaging the cell membrane in two ways"}, {"id": "d", "text": "inhibiting cell wall synthesis twice"}]'::jsonb, 'a', 'Sulfonamides inhibit dihydropteroate synthase and trimethoprim inhibits dihydrofolate reductase. The two together are synergistic and bactericidal. Protein synthesis is the target of the aminoglycosides, and membrane damage is the action of the polymyxins. These two drugs act on a single pathway, one step apart.', 4,
  'medicine/pco441', 'q011'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco441' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco441' and k.depot_qid = 'q011')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Metronidazole is effective against',
  '[{"id": "a", "text": "Gram-positive aerobes only"}, {"id": "b", "text": "viruses"}, {"id": "c", "text": "all fungi"}, {"id": "d", "text": "anaerobic bacteria and protozoa such as Giardia and Trichomonas"}]'::jsonb, 'd', 'It is activated in anaerobic organisms. A disulfiram-like reaction can occur if alcohol is taken during treatment. It has no activity against viruses or against aerobic bacteria, because it needs an anaerobic environment to be activated.', 3,
  'medicine/pco441', 'q012'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'pco441' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pco441' and k.depot_qid = 'q012')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Grey baby syndrome is a toxicity of',
  '[{"id": "a", "text": "tetracycline"}, {"id": "b", "text": "gentamicin"}, {"id": "c", "text": "ampicillin"}, {"id": "d", "text": "chloramphenicol"}]'::jsonb, 'd', 'Newborns cannot conjugate chloramphenicol, so it accumulates, causing cardiovascular collapse. Tetracycline instead stains teeth.', 3,
  'medicine/pco441', 'q013'
from cgpa.courses c
