insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Vincristine, used in leukaemia and lymphoma, acts by',
  '[{"id": "a", "text": "cross-linking DNA strands"}, {"id": "b", "text": "binding tubulin and preventing microtubule formation, arresting cells in mitosis"}, {"id": "c", "text": "inhibiting dihydrofolate reductase"}, {"id": "d", "text": "inhibiting reverse transcriptase"}]'::jsonb, 'b', 'Without a mitotic spindle, dividing cells cannot complete mitosis. A dose-limiting toxicity is peripheral neuropathy. DNA cross-linking is the action of cisplatin.', 4,
