insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The SI unit of force, the newton, is equivalent to',
  '[{"id": "a", "text": "kg m s^-2"}, {"id": "b", "text": "kg m^2 s^-2"}, {"id": "c", "text": "kg m s^-1"}, {"id": "d", "text": "kg s^-2"}]'::jsonb, 'a', 'F = ma gives kg x m/s^2. The unit kg m^2 s^-2 is the joule, the unit of energy, which is the nearest wrong choice.', 2,
  'medicine/phy101', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
