insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The dimensions of work (or energy) are',
  '[{"id": "a", "text": "MLT^-2"}, {"id": "b", "text": "ML^2T^-3"}, {"id": "c", "text": "MLT^-1"}, {"id": "d", "text": "ML^2T^-2"}]'::jsonb, 'd', 'Work = force x distance = (MLT^-2)(L) = ML^2T^-2. The dimensions MLT^-2 belong to force, while ML^2T^-3 are those of power.', 3,
  'medicine/phy101', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A car starts from rest and accelerates uniformly at 4 m/s^2 over a distance of 50 m. Its final speed is',
  '[{"id": "a", "text": "10 m/s"}, {"id": "b", "text": "40 m/s"}, {"id": "c", "text": "20 m/s"}, {"id": "d", "text": "200 m/s"}]'::jsonb, 'c', 'v^2 = u^2 + 2as = 0 + 2(4)(50) = 400, so v = 20 m/s. The value 400 is v squared, not v.', 3,
  'medicine/phy101', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A ball is thrown at 20 m/s at 30 degrees above the horizontal on level ground. Taking g = 10 m/s^2, its range is about',
  '[{"id": "a", "text": "40.0 m"}, {"id": "b", "text": "34.6 m"}, {"id": "c", "text": "20.0 m"}, {"id": "d", "text": "17.3 m"}]'::jsonb, 'b', 'R = u^2 sin(2 theta) / g = 400 x sin 60 / 10 = 34.6 m. The 40 m figure is the range at 45 degrees, the maximum for this speed. The value 20.0 m uses sin 30 in place of sin 60, and 17.3 m leaves out the factor of 2 in the double-angle formula.', 4,
  'medicine/phy101', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A stone is thrown vertically upwards at 20 m/s. Taking g = 10 m/s^2 and ignoring air resistance, it returns to the thrower after',
  '[{"id": "a", "text": "2 s"}, {"id": "b", "text": "4 s"}, {"id": "c", "text": "8 s"}, {"id": "d", "text": "20 s"}]'::jsonb, 'b', 'Time to the top is u/g = 2 s, and the return takes the same time, so the total is 4 s. The 2 s figure is only the upward half.', 3,
  'medicine/phy101', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A net force of 20 N acts on a 5 kg mass. The acceleration is',
  '[{"id": "a", "text": "4 m/s^2"}, {"id": "b", "text": "100 m/s^2"}, {"id": "c", "text": "0.25 m/s^2"}, {"id": "d", "text": "25 m/s^2"}]'::jsonb, 'a', 'a = F / m = 20 / 5 = 4 m/s^2. Multiplying force and mass gives 100, which confuses the formula.', 2,
  'medicine/phy101', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A 2 kg trolley moving at 6 m/s collides with a stationary 4 kg trolley and they stick together. Their common speed is',
  '[{"id": "a", "text": "3 m/s"}, {"id": "b", "text": "6 m/s"}, {"id": "c", "text": "1.5 m/s"}, {"id": "d", "text": "2 m/s"}]'::jsonb, 'd', 'Momentum is conserved: 2 x 6 = (2 + 4) v, so v = 2 m/s. Taking the average of the speeds, 3 m/s, ignores the unequal masses. A common speed of 6 m/s would mean the added mass had no effect, and the speed must fall because the moving mass increases.', 3,
  'medicine/phy101', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A force of 10 N moves an object 5 m, with the force at 60 degrees to the displacement. The work done is',
  '[{"id": "a", "text": "50 J"}, {"id": "b", "text": "43.3 J"}, {"id": "c", "text": "25 J"}, {"id": "d", "text": "5 J"}]'::jsonb, 'c', 'Work = F d cos(theta) = 10 x 5 x 0.5 = 25 J. Using sin 60 gives 43.3 J, which resolves the force in the wrong direction.', 3,
  'medicine/phy101', 'q008'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q008')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Mathematical Proofs']::text[], 'When the speed of a car doubles, its kinetic energy',
  '[{"id": "a", "text": "doubles"}, {"id": "b", "text": "becomes eight times as great"}, {"id": "c", "text": "becomes four times as great"}, {"id": "d", "text": "stays the same"}]'::jsonb, 'c', 'KE = 1/2 m v^2, so it depends on the square of the speed. Doubling v gives 2 squared = 4 times the energy. Eight times would be a cube law, and ''stays the same'' ignores speed altogether.', 3,
  'medicine/phy101', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A 50 kg load is lifted through 4 m in 10 s. Taking g = 10 m/s^2, the average power is',
  '[{"id": "a", "text": "2000 W"}, {"id": "b", "text": "200 W"}, {"id": "c", "text": "20 W"}, {"id": "d", "text": "500 W"}]'::jsonb, 'b', 'Work = mgh = 50 x 10 x 4 = 2000 J, and power = 2000 / 10 = 200 W. The figure 2000 is the work in joules, not the power.', 3,
  'medicine/phy101', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A body moves in a circle of radius 5 m at a constant speed of 10 m/s. Its centripetal acceleration is',
  '[{"id": "a", "text": "20 m/s^2"}, {"id": "b", "text": "2 m/s^2"}, {"id": "c", "text": "50 m/s^2"}, {"id": "d", "text": "500 m/s^2"}]'::jsonb, 'a', 'a = v^2 / r = 100 / 5 = 20 m/s^2, directed towards the centre. Dividing speed by radius gives 2, which leaves out the squaring. The value 2 m/s^2 is v / r, 50 m/s^2 is v x r, and 500 m/s^2 is v^2 x r.', 3,
  'medicine/phy101', 'q011'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q011')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'A 60 kg person is on a planet where g = 5 m/s^2. Their mass and weight there are',
  '[{"id": "a", "text": "30 kg and 300 N"}, {"id": "b", "text": "60 kg and 600 N"}, {"id": "c", "text": "300 kg and 60 N"}, {"id": "d", "text": "60 kg and 300 N"}]'::jsonb, 'd', 'Mass does not depend on location, so it remains 60 kg. Weight = mg = 60 x 5 = 300 N.', 2,
  'medicine/phy101', 'q012'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q012')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A 10 kg block on a horizontal surface just begins to slide when a horizontal force of 30 N is applied. Taking g = 10 m/s^2, the coefficient of limiting friction is',
  '[{"id": "a", "text": "3.0"}, {"id": "b", "text": "0.03"}, {"id": "c", "text": "0.1"}, {"id": "d", "text": "0.3"}]'::jsonb, 'd', 'Normal reaction = mg = 100 N, and mu = F / R = 30 / 100 = 0.3. Dividing the other way gives 3.3, which makes friction larger than the normal force. The value 0.03 is a slip of a power of ten, and 0.1 does not follow from 30 / 100.', 3,
  'medicine/phy101', 'q013'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy101' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q013')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A mass on a spring oscillates with period T. If the mass is increased to four times its value, the new period is',
  '[{"id": "a", "text": "4T"}, {"id": "b", "text": "T/2"}, {"id": "c", "text": "2T"}, {"id": "d", "text": "T/4"}]'::jsonb, 'c', 'T = 2 pi sqrt(m/k), so quadrupling m multiplies T by the square root of 4, which is 2. 4T would hold if the period were proportional to the mass, and T/2 or T/4 would mean a heavier mass oscillates faster, which is wrong.', 4,
  'medicine/phy101', 'q014'
from cgpa.courses c
