  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy101' and k.depot_qid = 'q014')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A spring extends by 0.05 m when a force of 10 N is applied. Its spring constant is',
  '[{"id": "a", "text": "0.5 N/m"}, {"id": "b", "text": "200 N/m"}, {"id": "c", "text": "2 N/m"}, {"id": "d", "text": "0.005 N/m"}]'::jsonb, 'b', 'k = F / x = 10 / 0.05 = 200 N/m. Multiplying the two numbers gives 0.5, which inverts the relationship. The value 0.005 divides in the wrong order, and 2 does not follow from the numbers given.', 3,
  'medicine/phy101', 'q015'
