insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'An object weighs 8 N in air and 5 N when fully immersed in water. The upthrust on the object is',
  '[{"id": "a", "text": "3 N"}, {"id": "b", "text": "13 N"}, {"id": "c", "text": "5 N"}, {"id": "d", "text": "8 N"}]'::jsonb, 'a', 'Upthrust = weight in air - apparent weight in water = 8 - 5 = 3 N. The apparent weight is not the upthrust.', 2,
  'medicine/phy101', 'q016'
