insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'The gauge pressure at a depth of 10 m in water (density 1000 kg/m^3, g = 10 m/s^2) is',
  '[{"id": "a", "text": "1 x 10^5 Pa"}, {"id": "b", "text": "1 x 10^3 Pa"}, {"id": "c", "text": "1 x 10^4 Pa"}, {"id": "d", "text": "1 x 10^6 Pa"}]'::jsonb, 'a', 'P = h rho g = 10 x 1000 x 10 = 1 x 10^5 Pa. This is about one atmosphere on top of the surface pressure. The value 1 x 10^4 Pa leaves out g, and the others are slips of a power of ten.', 3,
  'medicine/phy101', 'q017'
