insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Water flows steadily through a pipe that narrows to half its cross-sectional area. The speed of the water in the narrow section is',
  '[{"id": "a", "text": "half that in the wide section"}, {"id": "b", "text": "the same as in the wide section"}, {"id": "c", "text": "four times that in the wide section"}, {"id": "d", "text": "twice that in the wide section"}]'::jsonb, 'd', 'The continuity equation gives A1 v1 = A2 v2, so halving the area doubles the speed. Slower flow in the narrow section would contradict conservation of mass.', 3,
  'medicine/phy101', 'q018'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
