insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A uniform metre rule is pivoted at its 50 cm mark. A 2 N weight hangs at the 20 cm mark. Where must a 3 N weight hang to balance it?',
  '[{"id": "a", "text": "At the 80 cm mark"}, {"id": "b", "text": "At the 75 cm mark"}, {"id": "c", "text": "At the 70 cm mark"}, {"id": "d", "text": "At the 60 cm mark"}]'::jsonb, 'c', 'Clockwise and anticlockwise moments must match: 2 x 30 = 3 x d, so d = 20 cm from the pivot, which is the 70 cm mark. The 80 cm mark is 30 cm from the pivot, so it would over-balance.', 4,
  'medicine/phy101', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
