insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Mathematical Proofs']::text[], 'If the distance between two masses is doubled, the gravitational force between them becomes',
  '[{"id": "a", "text": "half of its original value"}, {"id": "b", "text": "one quarter of its original value"}, {"id": "c", "text": "twice its original value"}, {"id": "d", "text": "four times its original value"}]'::jsonb, 'b', 'Newton''s law gives a force proportional to 1 / r^2, so doubling r divides the force by 4. A half would apply to an inverse (not inverse-square) law.', 3,
  'medicine/phy101', 'q020'
