insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'How much heat is needed to raise the temperature of 2 kg of water by 10 degrees C? (specific heat capacity of water = 4200 J/kg C)',
  '[{"id": "a", "text": "84,000 J"}, {"id": "b", "text": "8,400 J"}, {"id": "c", "text": "840 J"}, {"id": "d", "text": "420,000 J"}]'::jsonb, 'a', 'Q = m c delta T = 2 x 4200 x 10 = 84,000 J. A factor-of-ten slip gives the other values. The value 8,400 J leaves out the temperature change.', 2,
  'medicine/phy102', 'q001'
from cgpa.courses c
