insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'How much heat is needed to melt 0.1 kg of ice at 0 degrees C? (specific latent heat of fusion = 3.34 x 10^5 J/kg)',
  '[{"id": "a", "text": "334,000 J"}, {"id": "b", "text": "3,340 J"}, {"id": "c", "text": "0 J, since the temperature does not change"}, {"id": "d", "text": "33,400 J"}]'::jsonb, 'd', 'Q = m L = 0.1 x 334,000 = 33,400 J. The temperature stays at 0 degrees C, but heat is still needed to change the state.', 3,
  'medicine/phy102', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
