insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A gas absorbs 500 J of heat and does 200 J of work on its surroundings. Its internal energy',
  '[{"id": "a", "text": "increases by 700 J"}, {"id": "b", "text": "decreases by 300 J"}, {"id": "c", "text": "increases by 300 J"}, {"id": "d", "text": "increases by 500 J"}]'::jsonb, 'c', 'First law: delta U = Q - W = 500 - 200 = +300 J. Adding the work would be correct only if work were done ON the gas.', 3,
  'medicine/phy102', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
