insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A sound wave of frequency 50 Hz has wavelength 6.8 m. Its speed is',
  '[{"id": "a", "text": "7.35 m/s"}, {"id": "b", "text": "340 m/s"}, {"id": "c", "text": "136 m/s"}, {"id": "d", "text": "3400 m/s"}]'::jsonb, 'b', 'v = f lambda = 50 x 6.8 = 340 m/s. Dividing the wavelength by the frequency gives 0.136, which inverts the formula. The value 7.35 m/s divides the frequency by the wavelength.', 2,
  'medicine/phy102', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy102' and c.approval_status = 'approved'
