insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A shout produces an echo from a cliff after 2.0 s. If sound travels at 340 m/s, the cliff is',
  '[{"id": "a", "text": "680 m away"}, {"id": "b", "text": "340 m away"}, {"id": "c", "text": "170 m away"}, {"id": "d", "text": "1,360 m away"}]'::jsonb, 'b', 'The sound travels to the cliff and back, so the distance one way is v x t / 2 = 340 x 2 / 2 = 340 m. Using the full time gives 680 m. The value 170 m halves the distance a second time, and 1,360 m doubles it twice.', 3,
  'medicine/phy102', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy102' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy102' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'The refractive index of a glass is 1.5. If the speed of light in a vacuum is 3 x 10^8 m/s, the speed of light in the glass is',
  '[{"id": "a", "text": "2 x 10^8 m/s"}, {"id": "b", "text": "4.5 x 10^8 m/s"}, {"id": "c", "text": "1.5 x 10^8 m/s"}, {"id": "d", "text": "3 x 10^8 m/s"}]'::jsonb, 'a', 'n = c / v, so v = c / n = 3 x 10^8 / 1.5 = 2 x 10^8 m/s. Light always slows in a denser medium, so a larger value is impossible. A speed of 4.5 x 10^8 m/s multiplies by n and exceeds the speed in a vacuum, and 3 x 10^8 m/s is the vacuum value itself.', 3,
  'medicine/phy102', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy102' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy102' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Total internal reflection can occur only when light travels',
  '[{"id": "a", "text": "from a less dense to a denser medium at any angle"}, {"id": "b", "text": "from a denser to a less dense medium at an angle below the critical angle"}, {"id": "c", "text": "through a vacuum"}, {"id": "d", "text": "from a denser to a less dense medium at an angle above the critical angle"}]'::jsonb, 'd', 'Both conditions are needed: a denser-to-rarer path and an angle of incidence greater than the critical angle. Below the critical angle, some light is refracted out.', 4,
  'medicine/phy102', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy102' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy102' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'An object is placed 30 cm from a converging lens of focal length 10 cm. The image is formed at a distance of',
  '[{"id": "a", "text": "7.5 cm from the lens"}, {"id": "b", "text": "20 cm from the lens"}, {"id": "c", "text": "15 cm from the lens"}, {"id": "d", "text": "30 cm from the lens"}]'::jsonb, 'c', '1/v = 1/f - 1/u = 1/10 - 1/30 = 2/30, so v = 15 cm (real image). The focal length of 10 cm would apply only to an object at infinity.', 4,
  'medicine/phy102', 'q008'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
