order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'Two resistors of 6 ohms and 3 ohms are connected in parallel. Their combined resistance is',
  '[{"id": "a", "text": "9 ohms"}, {"id": "b", "text": "4.5 ohms"}, {"id": "c", "text": "2 ohms"}, {"id": "d", "text": "18 ohms"}]'::jsonb, 'c', '1/R = 1/6 + 1/3 = 3/6, so R = 2 ohms. The value 9 ohms is the series combination, and a parallel total is always less than the smaller resistor. The value 4.5 ohms is the mean of the two resistors, and 18 ohms is their product.', 3,
  'medicine/phy102', 'q009'
from cgpa.courses c
