  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy102' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A potential difference of 12 V is applied across a 4 ohm resistor. The current is',
  '[{"id": "a", "text": "48 A"}, {"id": "b", "text": "3 A"}, {"id": "c", "text": "0.33 A"}, {"id": "d", "text": "8 A"}]'::jsonb, 'b', 'I = V / R = 12 / 4 = 3 A. Multiplying 12 and 4 gives 48, which leaves out Ohm''s law. The value 0.33 A inverts V / R, and 8 A subtracts the two numbers.', 2,
  'medicine/phy102', 'q010'
