insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A bulb is rated 60 W for a 240 V supply. The current it draws at its rated voltage is',
  '[{"id": "a", "text": "0.25 A"}, {"id": "b", "text": "4 A"}, {"id": "c", "text": "14,400 A"}, {"id": "d", "text": "180 A"}]'::jsonb, 'a', 'P = I V, so I = 60 / 240 = 0.25 A. The value 4 A comes from inverting the ratio. The value 14,400 A multiplies power and voltage, and 180 A subtracts one from the other.', 3,
  'medicine/phy102', 'q011'
