insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A 2 kW heater runs for 3 hours. The energy used is',
  '[{"id": "a", "text": "1.5 kWh"}, {"id": "b", "text": "0.67 kWh"}, {"id": "c", "text": "5 kWh"}, {"id": "d", "text": "6 kWh"}]'::jsonb, 'd', 'Energy = power x time = 2 x 3 = 6 kWh. Dividing power by time gives 0.67. The value 1.5 kWh divides 3 by 2, and 5 kWh adds the two numbers.', 2,
  'medicine/phy102', 'q012'
from cgpa.courses c
