order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The direction of the force on a current-carrying conductor in a magnetic field is given by',
  '[{"id": "a", "text": "Fleming''s right-hand rule"}, {"id": "b", "text": "Lenz''s law"}, {"id": "c", "text": "Ohm''s law"}, {"id": "d", "text": "Fleming''s left-hand rule"}]'::jsonb, 'd', 'The left-hand rule applies to motors, where current produces a force. The right-hand rule gives the induced current in a generator, so it is the nearest wrong choice.', 3,
  'medicine/phy102', 'q013'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
