select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'An ideal transformer has 1000 turns on its primary coil and 100 turns on its secondary. If the primary voltage is 240 V, the secondary voltage is',
  '[{"id": "a", "text": "2,400 V"}, {"id": "b", "text": "24 V"}, {"id": "c", "text": "10 V"}, {"id": "d", "text": "240 V"}]'::jsonb, 'b', 'Vs / Vp = Ns / Np, so Vs = 240 x 100 / 1000 = 24 V. A step-down transformer lowers the voltage. A secondary with fewer turns lowers the voltage, so 240 V and 2,400 V are impossible for this ratio.', 3,
  'medicine/phy102', 'q015'
from cgpa.courses c
