insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A radioactive isotope has a half-life of 4 days. The fraction remaining after 12 days is',
  '[{"id": "a", "text": "1/8"}, {"id": "b", "text": "1/3"}, {"id": "c", "text": "1/4"}, {"id": "d", "text": "1/12"}]'::jsonb, 'a', '12 days is 3 half-lives, so the fraction is (1/2)^3 = 1/8. Dividing by 12 ignores the exponential decay. The value 1/4 is the fraction left after only two half-lives, and 1/3 and 1/12 do not follow from any number of half-lives.', 3,
  'medicine/phy102', 'q017'
