select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'To find a spring''s extension correctly, the original length should be measured',
  '[{"id": "a", "text": "with the spring lying on the table unloaded"}, {"id": "b", "text": "after the largest load has been removed, ignoring the hanger"}, {"id": "c", "text": "with the empty hanger attached and the spring straight"}, {"id": "d", "text": "at any time, since the original length is not needed"}]'::jsonb, 'c', 'The hanger always loads the spring, so the reference length includes it. A spring measured lying flat is not straight under the same conditions.', 3,
  'medicine/phy107', 'q003'
