insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A metre rule is pivoted at the 50 cm mark. A 100 g mass hangs at the 20 cm mark, and an unknown mass at the 70 cm mark balances it. The unknown mass is',
  '[{"id": "a", "text": "100 g"}, {"id": "b", "text": "150 g"}, {"id": "c", "text": "67 g"}, {"id": "d", "text": "250 g"}]'::jsonb, 'b', 'Moments balance: 100 x 30 = m x 20, so m = 150 g. The 67 g value inverts the distances. The unknown mass hangs nearer the pivot (20 cm against 30 cm), so it must be heavier than 100 g, which rules out 100 g and 67 g.', 4,
  'medicine/phy107', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy107' and k.depot_qid = 'q004')
