insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'The centre of gravity of a uniform metre rule lies at the',
  '[{"id": "a", "text": "0 cm mark"}, {"id": "b", "text": "50 cm mark"}, {"id": "c", "text": "25 cm mark"}, {"id": "d", "text": "100 cm mark"}]'::jsonb, 'b', 'A uniform rule''s weight acts at its midpoint, which is the 50 cm mark on a metre rule. This is also the pivot position used in balance experiments. The 0 cm and 100 cm marks are the ends, and 25 cm is a quarter point. None of them is the midpoint.', 1,
  'medicine/phy107', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy107' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'An inclined plane makes an angle of 30 degrees with the horizontal. Its velocity ratio (for a smooth plane) is',
  '[{"id": "a", "text": "2"}, {"id": "b", "text": "0.5"}, {"id": "c", "text": "1.73"}, {"id": "d", "text": "30"}]'::jsonb, 'a', 'VR = 1 / sin(theta) = 1 / 0.5 = 2. The value 0.5 is sin 30, which inverts the ratio. The value 30 is the angle itself, not a ratio, and 1.73 is tan 60.', 3,
  'medicine/phy107', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
