insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A pulley system with a velocity ratio of 4 lifts a load of 80 N with an effort of 25 N. Its efficiency is',
  '[{"id": "a", "text": "32%"}, {"id": "b", "text": "125%"}, {"id": "c", "text": "20%"}, {"id": "d", "text": "80%"}]'::jsonb, 'd', 'MA = 80 / 25 = 3.2, so efficiency = MA / VR x 100 = 3.2 / 4 = 80%. An efficiency above 100% is impossible, which rules out 125%. The value 32% reads the mechanical advantage of 3.2 as a percentage, and 125% would mean the machine gives out more work than it takes in.', 4,
  'medicine/phy107', 'q007'
