  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Procedural / supply chain']::text[], 'To reduce the effect of reaction time when timing a pendulum, it is best to',
  '[{"id": "a", "text": "time one oscillation with great care"}, {"id": "b", "text": "start the stopwatch before releasing the bob"}, {"id": "c", "text": "use a very long string"}, {"id": "d", "text": "time 20 oscillations and divide the total by 20"}]'::jsonb, 'd', 'Reaction time adds the same small error to the total, so a longer total makes it a smaller share of the result. One carefully timed oscillation still carries the full reaction-time error as a large share, and a long string lengthens the period without removing the timing error.', 3,
  'medicine/phy107', 'q013'
