insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'A stopwatch with a reaction error of 0.2 s times 10 oscillations of a 1 s pendulum. The percentage error in the total time is about',
  '[{"id": "a", "text": "20%"}, {"id": "b", "text": "0.2%"}, {"id": "c", "text": "2%"}, {"id": "d", "text": "10%"}]'::jsonb, 'c', 'Percentage error = 0.2 / 10 x 100 = 2%. Timing a single swing would give 20%, which shows why many oscillations are timed.', 3,
  'medicine/phy107', 'q014'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy107' and k.depot_qid = 'q014')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Abstract / Visual']::text[], 'In a Hooke''s law experiment, a graph of load against extension curves away from a straight line beyond a certain load. This point marks the',
  '[{"id": "a", "text": "breaking stress"}, {"id": "b", "text": "elastic limit (or limit of proportionality)"}, {"id": "c", "text": "yield of the balance"}, {"id": "d", "text": "centre of gravity of the spring"}]'::jsonb, 'b', 'Past that point the extension is no longer proportional to the load, and the spring may not return to its original length.', 3,
  'medicine/phy107', 'q015'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy107' and k.depot_qid = 'q015')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A trolley covers 2.0 m in 4.0 s at constant speed. Its speed is',
  '[{"id": "a", "text": "0.50 m/s"}, {"id": "b", "text": "8.0 m/s"}, {"id": "c", "text": "2.0 m/s"}, {"id": "d", "text": "0.25 m/s"}]'::jsonb, 'a', 'Speed = distance / time = 2.0 / 4.0 = 0.50 m/s. Multiplying the figures gives 8.0, which confuses the operation.', 1,
  'medicine/phy107', 'q016'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy107' and k.depot_qid = 'q016')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'In a Young''s modulus experiment on a wire, the diameter of the wire is best measured with a',
  '[{"id": "a", "text": "micrometer screw gauge, at several points along the wire"}, {"id": "b", "text": "metre rule, once at the middle"}, {"id": "c", "text": "stopwatch"}, {"id": "d", "text": "spring balance"}]'::jsonb, 'a', 'The cross-section area depends on the diameter, so it needs a precise instrument and repeated readings, because wires are not uniform.', 3,
  'medicine/phy107', 'q017'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy107' and k.depot_qid = 'q017')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'The volume of an irregular stone that will not fit in a measuring cylinder can be found using',
  '[{"id": "a", "text": "a vernier caliper"}, {"id": "b", "text": "a stopwatch and a ruler"}, {"id": "c", "text": "a spring balance only"}, {"id": "d", "text": "a displacement (eureka) can and a measuring cylinder"}]'::jsonb, 'd', 'The water displaced by the submerged stone is collected and measured, and its volume equals the stone''s volume. A vernier caliper measures length, not the volume of an irregular shape, a stopwatch and ruler give no volume, and a spring balance measures weight.', 2,
  'medicine/phy107', 'q018'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy107' and k.depot_qid = 'q018')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'Before using a beam balance to weigh a sample, the user should first',
  '[{"id": "a", "text": "place the heaviest mass on the pan"}, {"id": "b", "text": "avoid levelling it"}, {"id": "c", "text": "check that it reads zero with nothing on the pan and adjust if needed"}, {"id": "d", "text": "tap the sample to remove dust"}]'::jsonb, 'c', 'A balance with a zero error gives every reading the same error, so it must be zeroed first. Placing the heaviest mass first or skipping levelling adds errors, and tapping the sample does nothing about the instrument''s zero.', 2,
  'medicine/phy107', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy107' and k.depot_qid = 'q019')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Procedural / supply chain']::text[], 'When a wire is stretched in a laboratory experiment, safety requires that',
  '[{"id": "a", "text": "the wire is stretched until it breaks"}, {"id": "b", "text": "goggles are worn and a soft pad is placed under the hanging masses"}, {"id": "c", "text": "masses are hung without any pad"}, {"id": "d", "text": "students stand directly beneath the load"}]'::jsonb, 'b', 'A wire can snap and fling pieces, and the load can fall, so eyes and feet must be protected. Stretching the wire to breaking, hanging masses with no pad and standing under the load each invite injury.', 2,
  'medicine/phy107', 'q020'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy107' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy107' and k.depot_qid = 'q020')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Abstract / Visual']::text[], 'In an Ohm''s law experiment, a graph of potential difference (y-axis) against current (x-axis) is a straight line through the origin with slope 5 V/A. The resistance of the conductor is',
  '[{"id": "a", "text": "5 ohms"}, {"id": "b", "text": "0.2 ohms"}, {"id": "c", "text": "25 ohms"}, {"id": "d", "text": "1 ohm"}]'::jsonb, 'a', 'Slope = V / I = R, so R = 5 ohms. The value 0.2 ohms is the reciprocal and would be the slope if the axes were reversed.', 3,
  'medicine/phy108', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'In a metre bridge, a 10 ohm resistor is in the left gap and an unknown resistance X is in the right gap. The balance point is 40.0 cm from the left end. The value of X is',
  '[{"id": "a", "text": "6.7 ohms"}, {"id": "b", "text": "10 ohms"}, {"id": "c", "text": "25 ohms"}, {"id": "d", "text": "15 ohms"}]'::jsonb, 'd', 'R / X = l / (100 - l), so X = 10 x 60 / 40 = 15 ohms. Swapping the lengths gives 6.7 ohms. The value 10 ohms would be correct only if the balance point were at 50 cm, and 25 ohms adds 10 and 15.', 4,
  'medicine/phy108', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Abstract / Visual']::text[], 'A graph of terminal voltage V against current I for a cell is a straight line with an intercept of 1.5 V on the V axis and a slope of -0.5 V/A. The internal resistance of the cell is',
  '[{"id": "a", "text": "1.5 ohms"}, {"id": "b", "text": "3.0 ohms"}, {"id": "c", "text": "0.5 ohms"}, {"id": "d", "text": "0.33 ohms"}]'::jsonb, 'c', 'V = E - I r, so the slope is -r and the intercept is E. The internal resistance is 0.5 ohms, and the 1.5 V intercept is the emf. The slope gives the internal resistance, so 1.5 ohms mistakes the intercept for it.', 4,
  'medicine/phy108', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A potentiometer wire is used to compare potential differences because, for a uniform wire carrying a steady current,',
  '[{"id": "a", "text": "the potential drop is proportional to the square of the length"}, {"id": "b", "text": "the potential drop is proportional to the length of the wire"}, {"id": "c", "text": "the current changes along the wire"}, {"id": "d", "text": "the resistance changes along the wire"}]'::jsonb, 'b', 'A uniform wire has a uniform resistance per unit length, so the potential difference between two points is proportional to the length between them.', 4,
  'medicine/phy108', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'The focal length of a converging lens can be estimated quickly by',
  '[{"id": "a", "text": "holding the lens close to the object"}, {"id": "b", "text": "focusing a distant object on a screen and measuring the lens-to-screen distance"}, {"id": "c", "text": "measuring the thickness of the lens"}, {"id": "d", "text": "viewing a nearby candle through the lens"}]'::jsonb, 'b', 'Rays from a distant object are almost parallel, so the image forms at the focal plane. Holding the lens close to the object or viewing a nearby candle does not form a sharp image at the focal plane, and the thickness of the lens does not give its focal length.', 2,
  'medicine/phy108', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'In a lens experiment, an object distance of 20 cm gives an image distance of 20 cm. The focal length is',
  '[{"id": "a", "text": "10 cm"}, {"id": "b", "text": "20 cm"}, {"id": "c", "text": "40 cm"}, {"id": "d", "text": "5 cm"}]'::jsonb, 'a', '1/f = 1/u + 1/v = 1/20 + 1/20 = 1/10, so f = 10 cm. Taking the object distance as f would assume the object is at infinity.', 3,
  'medicine/phy108', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A pin appears to be 9 cm below the surface of water in a beaker that is actually 12 cm deep. The refractive index of water is about',
  '[{"id": "a", "text": "0.75"}, {"id": "b", "text": "3.0"}, {"id": "c", "text": "1.5"}, {"id": "d", "text": "1.33"}]'::jsonb, 'd', 'n = real depth / apparent depth = 12 / 9 = 1.33. The figure 0.75 inverts the ratio and would be below 1, which is impossible for water.', 3,
  'medicine/phy108', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'In a pin experiment on a glass block, the angle of incidence is 60 degrees and the angle of refraction is 35 degrees. The refractive index of the glass is about (sin 60 = 0.866, sin 35 = 0.574)',
  '[{"id": "a", "text": "0.66"}, {"id": "b", "text": "1.7"}, {"id": "c", "text": "1.5"}, {"id": "d", "text": "2.1"}]'::jsonb, 'c', 'n = sin i / sin r = 0.866 / 0.574 = 1.51. The value 0.66 inverts the ratio. The value 1.7 divides the angles themselves instead of their sines.', 4,
  'medicine/phy108', 'q008'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q008')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A 0.2 kg metal at 100 degrees C is dropped into 0.1 kg of water at 20 degrees C and the final temperature is 30 degrees C. Ignoring the calorimeter, the specific heat capacity of the metal (water = 4200 J/kg C) is',
  '[{"id": "a", "text": "600 J/kg C"}, {"id": "b", "text": "4200 J/kg C"}, {"id": "c", "text": "300 J/kg C"}, {"id": "d", "text": "30 J/kg C"}]'::jsonb, 'c', 'Heat gained by water = 0.1 x 4200 x 10 = 4200 J. The metal loses 0.2 x c x 70 = 14c, so c = 300. Using the temperature change of water for the metal would give a different value.', 5,
  'medicine/phy108', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'In a calorimetry experiment, heat loss to the surroundings is reduced by',
  '[{"id": "a", "text": "using a larger open container"}, {"id": "b", "text": "lagging the calorimeter and covering it with a lid"}, {"id": "c", "text": "heating the water to a much higher temperature"}, {"id": "d", "text": "leaving the water uncovered"}]'::jsonb, 'b', 'Lagging and a lid reduce conduction, convection and evaporation, so more of the heat transfer stays in the system. A larger open container, much hotter water and leaving the water uncovered all increase the heat lost.', 3,
  'medicine/phy108', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'In a resonance tube experiment with a tuning fork of frequency 480 Hz, the first and second resonant lengths are 17.0 cm and 52.0 cm. The speed of sound is',
  '[{"id": "a", "text": "336 m/s"}, {"id": "b", "text": "168 m/s"}, {"id": "c", "text": "252 m/s"}, {"id": "d", "text": "456 m/s"}]'::jsonb, 'a', 'The difference between successive resonances is half a wavelength: 35 cm, so lambda = 0.70 m and v = f lambda = 480 x 0.70 = 336 m/s. The 168 m/s figure uses half the wavelength.', 5,
  'medicine/phy108', 'q011'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q011')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'In a sonometer experiment with the tension kept constant, shortening the vibrating length of the wire to half its value',
  '[{"id": "a", "text": "halves the frequency"}, {"id": "b", "text": "leaves the frequency unchanged"}, {"id": "c", "text": "quadruples the frequency"}, {"id": "d", "text": "doubles the frequency"}]'::jsonb, 'd', 'Frequency is inversely proportional to the vibrating length, so half the length gives twice the frequency. Frequency rises as length falls, so halving the length cannot halve the frequency, and quadrupling it would need a quarter of the length.', 3,
  'medicine/phy108', 'q012'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q012')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A voltmeter should have a very high resistance because',
  '[{"id": "a", "text": "it must carry the full circuit current"}, {"id": "b", "text": "it must be heated by the current"}, {"id": "c", "text": "it is placed in series"}, {"id": "d", "text": "it must draw almost no current from the circuit it measures"}]'::jsonb, 'd', 'A voltmeter is in parallel with a component, so a low resistance would divert current and change the voltage being measured.', 3,
  'medicine/phy108', 'q013'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q013')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'In an electrical experiment, the circuit should be switched off between readings because',
  '[{"id": "a", "text": "the ammeter cannot read continuously"}, {"id": "b", "text": "the battery gains charge when idle"}, {"id": "c", "text": "current heats the resistor and changes its resistance"}, {"id": "d", "text": "the connecting wires become magnetic"}]'::jsonb, 'c', 'Heating changes the resistance of most conductors, so readings taken with the current left on would not give a constant resistance.', 3,
  'medicine/phy108', 'q014'
