insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Procedural / supply chain']::text[], 'A resistor has colour bands brown, black, red and gold. Its value is',
  '[{"id": "a", "text": "1000 ohms with a 5% tolerance"}, {"id": "b", "text": "10 ohms with a 5% tolerance"}, {"id": "c", "text": "100 ohms with a 10% tolerance"}, {"id": "d", "text": "1200 ohms with a 5% tolerance"}]'::jsonb, 'a', 'Brown = 1, black = 0, red = multiplier 10^2, so 10 x 100 = 1000 ohms. Gold means 5% tolerance. Reading red as a plain ''2'' gives 102, which is wrong.', 4,
  'medicine/phy108', 'q016'
from cgpa.courses c
