insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'A silicon diode in forward bias begins to conduct appreciably at about',
  '[{"id": "a", "text": "0.7 V"}, {"id": "b", "text": "0.07 V"}, {"id": "c", "text": "7 V"}, {"id": "d", "text": "70 V"}]'::jsonb, 'a', 'Silicon junction diodes turn on at around 0.6 to 0.7 V. Germanium diodes turn on at a lower value, around 0.3 V. The value 0.07 V is far too low for silicon, and 7 V and 70 V are far above its turn-on voltage.', 3,
  'medicine/phy108', 'q017'
