  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q017')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A 10 kilohm resistor is in series with a 100 microfarad capacitor. The time constant of the circuit is',
  '[{"id": "a", "text": "10 s"}, {"id": "b", "text": "0.1 s"}, {"id": "c", "text": "1000 s"}, {"id": "d", "text": "1 s"}]'::jsonb, 'd', 'Time constant = R C = 10,000 x 100 x 10^-6 = 1 s. Forgetting that micro means 10^-6 gives the wrong power.', 4,
  'medicine/phy108', 'q018'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
