  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q018')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'In a Young''s double-slit experiment, light of wavelength 600 nm falls on slits 1.0 mm apart and the screen is 2.0 m away. The fringe spacing is',
  '[{"id": "a", "text": "0.3 mm"}, {"id": "b", "text": "3.0 mm"}, {"id": "c", "text": "1.2 mm"}, {"id": "d", "text": "1.2 cm"}]'::jsonb, 'c', 'Spacing = lambda D / d = 600 x 10^-9 x 2.0 / 1.0 x 10^-3 = 1.2 x 10^-3 m = 1.2 mm. Mixing up the units shifts the answer by factors of ten. The value 1.2 cm is ten times too large, and 0.3 mm and 3.0 mm do not follow from the formula.', 5,
  'medicine/phy108', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q019')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Abstract / Visual']::text[], 'During the cooling of molten naphthalene, the temperature remains constant for a time at about 80 degrees C because',
  '[{"id": "a", "text": "it is absorbing heat from the surroundings"}, {"id": "b", "text": "latent heat is released as it solidifies"}, {"id": "c", "text": "its specific heat capacity becomes zero"}, {"id": "d", "text": "the thermometer has stopped working"}]'::jsonb, 'b', 'The liquid gives out latent heat as it freezes, which balances the heat lost to the surroundings and keeps the temperature fixed.', 3,
  'medicine/phy108', 'q020'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'phy108' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy108' and k.depot_qid = 'q020')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A vernier caliper has a main scale graduated in millimetres, and 10 vernier divisions equal 9 main scale divisions. Its least count is',
  '[{"id": "a", "text": "0.1 mm"}, {"id": "b", "text": "0.01 mm"}, {"id": "c", "text": "1.0 mm"}, {"id": "d", "text": "0.9 mm"}]'::jsonb, 'a', 'Least count = 1 main division - 1 vernier division = 1 mm - 0.9 mm = 0.1 mm. The value 0.01 mm belongs to a micrometer screw gauge.', 3,
  'medicine/phy109', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A micrometer screw gauge has a pitch of 0.5 mm and 50 divisions on the thimble. Its least count is',
  '[{"id": "a", "text": "0.1 mm"}, {"id": "b", "text": "0.5 mm"}, {"id": "c", "text": "0.001 mm"}, {"id": "d", "text": "0.01 mm"}]'::jsonb, 'd', 'Least count = pitch / number of thimble divisions = 0.5 / 50 = 0.01 mm. The value 0.1 mm is the caliper figure. The value 0.5 mm is the pitch, not the least count, and 0.001 mm is finer than a screw gauge can read.', 3,
  'medicine/phy109', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'A micrometer shows a reading of +0.02 mm when its jaws are closed. A wire is measured at 5.43 mm on the same instrument. The corrected diameter is',
  '[{"id": "a", "text": "5.45 mm"}, {"id": "b", "text": "5.43 mm"}, {"id": "c", "text": "5.41 mm"}, {"id": "d", "text": "5.23 mm"}]'::jsonb, 'c', 'A positive zero error is subtracted: 5.43 - 0.02 = 5.41 mm. Adding it gives 5.45 mm, which makes the error larger. The value 5.43 mm ignores the zero error, and 5.23 mm subtracts it ten times over.', 3,
  'medicine/phy109', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Parallax error in reading a scale is caused by',
  '[{"id": "a", "text": "a worn zero mark on the instrument"}, {"id": "b", "text": "viewing the pointer or mark from a position that is not directly in line with it"}, {"id": "c", "text": "using an instrument with a small least count"}, {"id": "d", "text": "variations in room temperature"}]'::jsonb, 'b', 'Parallax arises from the eye''s position, so the reading shifts against the scale. A worn zero is a zero error, a different kind of systematic error.', 2,
  'medicine/phy109', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A student measures g as 9.6 m/s^2. The accepted value is 9.8 m/s^2. The percentage error is about',
  '[{"id": "a", "text": "0.2%"}, {"id": "b", "text": "2.0%"}, {"id": "c", "text": "20%"}, {"id": "d", "text": "4.0%"}]'::jsonb, 'b', 'Percentage error = |9.6 - 9.8| / 9.8 x 100 = 2.04%. Dividing by the measured value instead gives a slightly different figure, and 0.2% drops a factor of ten.', 3,
  'medicine/phy109', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'An error that always shifts readings in the same direction, such as an uncorrected zero error, is called a',
  '[{"id": "a", "text": "systematic error"}, {"id": "b", "text": "random error"}, {"id": "c", "text": "parallax error only"}, {"id": "d", "text": "gross blunder"}]'::jsonb, 'a', 'Systematic errors push every reading the same way and are not removed by averaging. Repeating readings reduces random error, which is the nearest wrong choice.', 2,
  'medicine/phy109', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'How many significant figures are in the measurement 0.004050 m?',
  '[{"id": "a", "text": "3"}, {"id": "b", "text": "5"}, {"id": "c", "text": "7"}, {"id": "d", "text": "4"}]'::jsonb, 'd', 'Leading zeros do not count. The digits 4, 0, 5 and 0 are significant, the zero between digits and the trailing zero after the decimal point both count.', 3,
  'medicine/phy109', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'The time for 20 oscillations of a pendulum is 36.0 s and its length is 0.80 m. Using g = 4 pi^2 l / T^2, the value of g is about',
  '[{"id": "a", "text": "9.81 m/s^2"}, {"id": "b", "text": "4.87 m/s^2"}, {"id": "c", "text": "9.75 m/s^2"}, {"id": "d", "text": "19.5 m/s^2"}]'::jsonb, 'c', 'T = 36.0 / 20 = 1.80 s, so g = 39.48 x 0.80 / 3.24 = 9.75 m/s^2. Using the time for 20 swings as T gives a far smaller figure, and 9.81 is the accepted value, not the computed one.', 4,
  'medicine/phy109', 'q008'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q008')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A graph of T^2 (y-axis) against length l (x-axis) for a simple pendulum has a slope of 4.0 s^2/m. The value of g is about',
  '[{"id": "a", "text": "16 m/s^2"}, {"id": "b", "text": "0.10 m/s^2"}, {"id": "c", "text": "9.87 m/s^2"}, {"id": "d", "text": "39.5 m/s^2"}]'::jsonb, 'c', 'T^2 = (4 pi^2 / g) l, so the slope is 4 pi^2 / g and g = 39.48 / 4.0 = 9.87 m/s^2. Using the slope directly as g, or inverting, gives the wrong figures.', 4,
  'medicine/phy109', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'A student reads a water level in a measuring cylinder. The correct way to take the reading is',
  '[{"id": "a", "text": "with the eye above the top of the meniscus"}, {"id": "b", "text": "with the eye level with the bottom of the meniscus"}, {"id": "c", "text": "from the top edge of the meniscus"}, {"id": "d", "text": "from the edge of the cylinder"}]'::jsonb, 'b', 'Water''s meniscus curves down, so the reading is taken at its bottom with the eye at the same level to avoid parallax. Reading from the top edge of the meniscus or from a tilted eye position introduces parallax error.', 2,
  'medicine/phy109', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'Which instrument is most suitable for measuring the diameter of a thin copper wire to 0.01 mm?',
  '[{"id": "a", "text": "Micrometer screw gauge"}, {"id": "b", "text": "Metre rule"}, {"id": "c", "text": "Vernier caliper"}, {"id": "d", "text": "Measuring tape"}]'::jsonb, 'a', 'A micrometer reads to 0.01 mm. A vernier caliper, the nearest wrong choice, reads only to 0.1 mm in the standard form.', 2,
  'medicine/phy109', 'q011'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
