  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q011')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A rectangle measures 2.5 cm by 4.0 cm. Its area in m^2 is',
  '[{"id": "a", "text": "1.0 x 10^-1 m^2"}, {"id": "b", "text": "1.0 x 10^-5 m^2"}, {"id": "c", "text": "10 m^2"}, {"id": "d", "text": "1.0 x 10^-3 m^2"}]'::jsonb, 'd', 'Area = 10 cm^2, and 1 cm^2 = 10^-4 m^2, so the area is 10 x 10^-4 = 10^-3 m^2. Dividing by only 100 gives the wrong power.', 4,
  'medicine/phy109', 'q012'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q012')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A rectangle has length 12.0 +/- 0.1 cm and width 5.0 +/- 0.1 cm. Its area, with uncertainty, is about',
  '[{"id": "a", "text": "60 +/- 0.1 cm^2"}, {"id": "b", "text": "60 +/- 0.2 cm^2"}, {"id": "c", "text": "60 +/- 4 cm^2"}, {"id": "d", "text": "60 +/- 2 cm^2"}]'::jsonb, 'd', 'Fractional uncertainties add: 0.1/12 + 0.1/5 = 0.0083 + 0.02 = 0.028. Multiply by 60 to get 1.7, which rounds to 2 cm^2. Adding the absolute errors directly (0.2) is wrong.', 5,
  'medicine/phy109', 'q013'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
