insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A stone of mass 54 g raises the water level in a measuring cylinder from 40 cm^3 to 60 cm^3. The density of the stone is',
  '[{"id": "a", "text": "0.9 g/cm^3"}, {"id": "b", "text": "1.35 g/cm^3"}, {"id": "c", "text": "2.7 g/cm^3"}, {"id": "d", "text": "5.4 g/cm^3"}]'::jsonb, 'c', 'Volume = 60 - 40 = 20 cm^3, so density = 54 / 20 = 2.7 g/cm^3. Using the final reading of 60 cm^3 as the volume gives 0.9. Using the initial reading of 40 cm^3 as the volume gives 1.35 g/cm^3.', 3,
  'medicine/phy109', 'q014'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q014')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Abstract / Visual']::text[], 'In an electrical experiment, the ammeter should be connected',
  '[{"id": "a", "text": "in parallel with the component, and the voltmeter in series"}, {"id": "b", "text": "in series with the component, and the voltmeter in parallel across it"}, {"id": "c", "text": "in parallel with both the component and the voltmeter"}, {"id": "d", "text": "in series with the voltmeter only"}]'::jsonb, 'b', 'The ammeter must carry the same current as the component, so it goes in series. The voltmeter measures the potential difference across the component, so it goes in parallel.', 2,
  'medicine/phy109', 'q015'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
