  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q015')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'The end of a metre rule is badly worn. To avoid an end error, a student should',
  '[{"id": "a", "text": "start measuring from the 1.00 cm mark and subtract 1.00 cm from the result"}, {"id": "b", "text": "start from the worn end anyway and add 1 cm"}, {"id": "c", "text": "avoid using a rule for the measurement"}, {"id": "d", "text": "double the reading"}]'::jsonb, 'a', 'A worn zero end makes readings uncertain, so the measurement starts from a clear mark, and that offset is removed from the final difference.', 3,
  'medicine/phy109', 'q016'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
