  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q016')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Readings of 5.01 cm, 5.02 cm and 5.01 cm are obtained for a length whose true value is 5.50 cm. These readings are',
  '[{"id": "a", "text": "precise but not accurate"}, {"id": "b", "text": "accurate but not precise"}, {"id": "c", "text": "both accurate and precise"}, {"id": "d", "text": "neither accurate nor precise"}]'::jsonb, 'a', 'The readings agree closely with each other (precise) but sit far from the true value (not accurate), which suggests a systematic error.', 3,
  'medicine/phy109', 'q017'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
