  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q017')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Canon / Administrative']::text[], array['Procedural / supply chain']::text[], 'When recording results in a table, units should be placed',
  '[{"id": "a", "text": "only after the final value"}, {"id": "b", "text": "with every value but not in the heading"}, {"id": "c", "text": "nowhere, since they are understood"}, {"id": "d", "text": "in the column heading, not repeated with each value"}]'::jsonb, 'd', 'Putting the unit in the heading keeps the table uncluttered and removes ambiguity about the quantity measured. Units after only the final value, repeated in every cell, or left out altogether would leave readers unsure or clutter the table.', 2,
  'medicine/phy109', 'q018'
from cgpa.courses c
