  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q018')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Procedural / supply chain']::text[], 'To reduce the percentage error in timing a pendulum with a hand-held stopwatch, a student should',
  '[{"id": "a", "text": "time one oscillation very carefully"}, {"id": "b", "text": "increase the amplitude to a large angle"}, {"id": "c", "text": "time many oscillations and divide the total time by the number"}, {"id": "d", "text": "use a lighter string"}]'::jsonb, 'c', 'The human reaction error is fixed (about 0.2 s), so spreading it over many oscillations shrinks it as a share of each period. One swing leaves the error large compared with the measured time.', 3,
  'medicine/phy109', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q019')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Procedural / supply chain']::text[], 'Random errors in a set of readings are best reduced by',
  '[{"id": "a", "text": "correcting the zero error of the instrument"}, {"id": "b", "text": "repeating the measurement several times and taking the mean"}, {"id": "c", "text": "reading the scale from a different angle each time"}, {"id": "d", "text": "recording only the first reading"}]'::jsonb, 'b', 'Random errors scatter readings on both sides of the true value, so averaging repeated readings cancels much of the scatter. Correcting a zero error deals with a systematic error instead.', 3,
  'medicine/phy109', 'q020'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'human-medicine' and c.slug = 'phy109' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/phy109' and k.depot_qid = 'q020')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'In a 70 kg adult man, total body water is about 60% of body weight. The approximate volume of intracellular fluid (two-thirds of the total) is',
  '[{"id": "a", "text": "28 L"}, {"id": "b", "text": "14 L"}, {"id": "c", "text": "42 L"}, {"id": "d", "text": "3 L"}]'::jsonb, 'a', 'Total body water = 0.6 x 70 = 42 L, and two-thirds of that is 28 L. The figure 14 L is the extracellular fluid, and 42 L is the total. The value 3 L is roughly the plasma volume.', 3,
  'medicine/pio201', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'pio201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Homeostasis in the body is mainly maintained by',
  '[{"id": "a", "text": "positive feedback mechanisms only"}, {"id": "b", "text": "voluntary control only"}, {"id": "c", "text": "random chemical changes"}, {"id": "d", "text": "negative feedback mechanisms"}]'::jsonb, 'd', 'Negative feedback opposes a change and restores the set point, as in the regulation of body temperature. Positive feedback amplifies a change, as in childbirth and blood clotting.', 2,
  'medicine/pio201', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'pio201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'The Na+/K+ ATPase pump moves',
  '[{"id": "a", "text": "2 sodium ions out and 3 potassium ions in"}, {"id": "b", "text": "3 sodium ions in and 2 potassium ions out"}, {"id": "c", "text": "3 sodium ions out of the cell and 2 potassium ions into the cell"}, {"id": "d", "text": "equal numbers of both ions in the same direction"}]'::jsonb, 'c', 'The unequal exchange makes the inside of the cell negative and helps to maintain the resting membrane potential, about -70 mV in neurones. The reversed or equal exchanges would not leave the inside of the cell negative.', 3,
  'medicine/pio201', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'pio201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'A solution that is isotonic to red blood cells is',
  '[{"id": "a", "text": "5% sodium chloride"}, {"id": "b", "text": "0.9% sodium chloride (normal saline)"}, {"id": "c", "text": "pure distilled water"}, {"id": "d", "text": "0.09% sodium chloride"}]'::jsonb, 'b', 'Red cells neither swell nor shrink in 0.9% saline. In distilled water they swell and burst, and in 5% saline they shrink.', 2,
  'medicine/pio201', 'q004'
