insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Red blood cells have a lifespan of about',
  '[{"id": "a", "text": "10 days"}, {"id": "b", "text": "120 days"}, {"id": "c", "text": "30 days"}, {"id": "d", "text": "1 year"}]'::jsonb, 'b', 'They are removed by the spleen and other macrophages. The lack of a nucleus limits repair, so the cells age after about four months. The values 10 days and 30 days are far too short for red cells, and platelets are the cells that last about 10 days.', 2,
  'medicine/pio201', 'q005'
