  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Erythropoietin, which stimulates red blood cell production, is secreted mainly by the',
  '[{"id": "a", "text": "kidney"}, {"id": "b", "text": "liver"}, {"id": "c", "text": "spleen"}, {"id": "d", "text": "pancreas"}]'::jsonb, 'a', 'The kidney releases it in response to hypoxia. The liver is the main source before birth, which is why it is the nearest wrong choice.', 3,
  'medicine/pio201', 'q006'
