order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Adult haemoglobin (HbA) is composed of',
  '[{"id": "a", "text": "four alpha chains"}, {"id": "b", "text": "two alpha and two gamma chains"}, {"id": "c", "text": "one globin chain and four haem groups"}, {"id": "d", "text": "two alpha and two beta globin chains, each with a haem group"}]'::jsonb, 'd', 'Four globin chains carry four haem groups, so one molecule can bind four oxygen molecules. Two alpha and two gamma chains make up fetal haemoglobin.', 3,
  'medicine/pio201', 'q007'
