insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'In sickle cell disease, the molecular defect is the substitution of',
  '[{"id": "a", "text": "glutamic acid for valine at position 6 of the alpha chain"}, {"id": "b", "text": "lysine for leucine in the gamma chain"}, {"id": "c", "text": "valine for glutamic acid at position 6 of the beta globin chain"}, {"id": "d", "text": "deletion of the whole beta gene"}]'::jsonb, 'c', 'The change makes HbS polymerise when deoxygenated, so cells sickle. The substitution is in the beta chain, not the alpha chain.', 4,
  'medicine/pio201', 'q008'
