insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A person with blood group A has',
  '[{"id": "a", "text": "B antigens on the red cells and anti-B antibodies in the plasma"}, {"id": "b", "text": "no antigens and both antibodies in the plasma"}, {"id": "c", "text": "A antigens on the red cells and anti-B antibodies in the plasma"}, {"id": "d", "text": "A and B antigens and no antibodies"}]'::jsonb, 'c', 'A person does not carry antibodies against their own antigens. Having A antigens, they have anti-B antibodies, and so they cannot receive group B blood.', 3,
  'medicine/pio201', 'q009'
