insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Procedural / supply chain']::text[], 'In an emergency, when the recipient''s blood group is not known, which red cells are normally issued?',
  '[{"id": "a", "text": "Group AB, Rh-positive"}, {"id": "b", "text": "Group O, preferably Rh-negative"}, {"id": "c", "text": "Group A, Rh-negative"}, {"id": "d", "text": "Group B, Rh-positive"}]'::jsonb, 'b', 'Group O cells lack A, B and D antigens, so they are unlikely to be attacked by the recipient''s antibodies. Rh-negative is preferred, especially for women of child-bearing age.', 3,
  'medicine/pio201', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
