insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Haemolytic disease of the newborn may occur when the mother is',
  '[{"id": "a", "text": "Rh-negative and the fetus is Rh-positive, in a second or later pregnancy"}, {"id": "b", "text": "Rh-positive and the fetus is Rh-negative"}, {"id": "c", "text": "group O and the father is group O"}, {"id": "d", "text": "Rh-negative and the fetus is Rh-negative"}]'::jsonb, 'a', 'The first Rh-positive pregnancy sensitises the mother, and her IgG antibodies cross the placenta in later pregnancies. Anti-D immunoglobulin prevents this. An Rh-positive mother has nothing to be sensitised against, two Rh-negative parents give no mismatch, and two group O parents give group O children.', 4,
  'medicine/pio201', 'q011'
