insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Platelets are formed in the bone marrow from',
  '[{"id": "a", "text": "erythroblasts"}, {"id": "b", "text": "lymphocytes"}, {"id": "c", "text": "megakaryocytes"}, {"id": "d", "text": "monocytes"}]'::jsonb, 'c', 'Fragments of the cytoplasm of megakaryocytes are released as platelets. The normal count is about 150 to 400 x 10^9 per litre. Erythroblasts give rise to red cells, lymphocytes are white cells, and monocytes become macrophages.', 3,
  'medicine/pio201', 'q014'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'pio201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q014')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'An increase in the number of which white cell is characteristic of helminth (worm) infestation and allergy?',
  '[{"id": "a", "text": "Neutrophils"}, {"id": "b", "text": "Eosinophils"}, {"id": "c", "text": "Basophils"}, {"id": "d", "text": "Monocytes"}]'::jsonb, 'b', 'Eosinophils attack parasites and are raised in allergic states. Neutrophils rise mainly in bacterial infection.', 3,
  'medicine/pio201', 'q015'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'pio201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q015')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'Iron deficiency anaemia typically produces red cells that are',
  '[{"id": "a", "text": "microcytic and hypochromic"}, {"id": "b", "text": "macrocytic and normochromic"}, {"id": "c", "text": "normocytic and hyperchromic"}, {"id": "d", "text": "sickle-shaped"}]'::jsonb, 'a', 'Little iron limits haemoglobin synthesis, so the cells are small and pale. Vitamin B12 or folate deficiency causes macrocytic (megaloblastic) anaemia.', 3,
  'medicine/pio201', 'q016'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'pio201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q016')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A man''s packed cell volume (haematocrit) is 45% and his blood volume is 5 L. The volume occupied by red cells is',
  '[{"id": "a", "text": "2.25 L"}, {"id": "b", "text": "0.45 L"}, {"id": "c", "text": "4.5 L"}, {"id": "d", "text": "22.5 L"}]'::jsonb, 'a', 'Red cell volume = 0.45 x 5 = 2.25 L. Treating 45% as 0.045 or 4.5 gives the wrong order of magnitude.', 3,
  'medicine/pio201', 'q017'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'pio201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q017')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A patient has a PCV of 45% and a red cell count of 5.0 x 10^12 per litre. The mean corpuscular volume (MCV) is',
  '[{"id": "a", "text": "9 fL"}, {"id": "b", "text": "225 fL"}, {"id": "c", "text": "900 fL"}, {"id": "d", "text": "90 fL"}]'::jsonb, 'd', 'MCV = PCV (%) x 10 / red cell count (in 10^12/L) = 45 x 10 / 5.0 = 90 fL, which is normal. Multiplying the two numbers gives 225. The values 9 fL and 900 fL are slips of a power of ten.', 4,
  'medicine/pio201', 'q018'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'pio201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q018')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'The plasma protein mainly responsible for the colloid oncotic pressure is',
  '[{"id": "a", "text": "fibrinogen"}, {"id": "b", "text": "gamma globulin"}, {"id": "c", "text": "albumin"}, {"id": "d", "text": "haemoglobin"}]'::jsonb, 'c', 'Albumin is the most abundant plasma protein, and it keeps water in the circulation. Low albumin causes oedema, as in the nephrotic syndrome. Fibrinogen is a clotting protein, gamma globulins are antibodies, and haemoglobin sits inside red cells, not in plasma.', 3,
  'medicine/pio201', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'pio201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q019')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pragmatic']::text[], array['Essential / definitive']::text[], 'Antibodies are produced by',
  '[{"id": "a", "text": "T lymphocytes"}, {"id": "b", "text": "plasma cells derived from B lymphocytes"}, {"id": "c", "text": "neutrophils"}, {"id": "d", "text": "platelets"}]'::jsonb, 'b', 'B cells differentiate into plasma cells, which secrete antibody. T lymphocytes provide cell-mediated immunity and help B cells, but do not secrete antibody themselves.', 3,
  'medicine/pio201', 'q020'
