  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/pio201' and k.depot_qid = 'q020')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Essential / definitive']::text[], 'Blood group (A, B, AB, O) is an example of which type of data?',
  '[{"id": "a", "text": "Nominal"}, {"id": "b", "text": "Ordinal"}, {"id": "c", "text": "Interval"}, {"id": "d", "text": "Ratio"}]'::jsonb, 'a', 'The categories have no natural order. Ordinal data, the nearest wrong choice, would have a ranked order such as mild, moderate or severe.', 2,
  'medicine/sta201', 'q001'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
