  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q001')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Essential / definitive']::text[], 'A pain score recorded as none, mild, moderate or severe is',
  '[{"id": "a", "text": "nominal data"}, {"id": "b", "text": "ratio data"}, {"id": "c", "text": "continuous data"}, {"id": "d", "text": "ordinal data"}]'::jsonb, 'd', 'The categories can be ranked, but the gaps between them are not equal or measurable. For this reason, the median is a more suitable summary than the mean.', 2,
  'medicine/sta201', 'q002'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q002')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'The median of the values 12, 7, 3, 15, 9 and 10 is',
  '[{"id": "a", "text": "9"}, {"id": "b", "text": "10"}, {"id": "c", "text": "9.5"}, {"id": "d", "text": "9.33"}]'::jsonb, 'c', 'Sorted values are 3, 7, 9, 10, 12 and 15. With an even number of values, the median is the mean of the middle two, (9 + 10) / 2 = 9.5. The mean of all six is 9.33. The values 9 and 10 each pick only one of the two middle numbers.', 3,
  'medicine/sta201', 'q003'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q003')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'The mode of the values 2, 3, 3, 4, 5, 5, 5, 6 is',
  '[{"id": "a", "text": "3"}, {"id": "b", "text": "5"}, {"id": "c", "text": "4"}, {"id": "d", "text": "5.5"}]'::jsonb, 'b', 'The mode is the value that appears most often. The value 5 occurs three times, while 3 occurs twice. The value 3 occurs twice and 4 once, and 5.5 is not in the data at all.', 2,
  'medicine/sta201', 'q004'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q004')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'The population standard deviation of the values 2, 4, 4, 4, 5, 5, 7, 9 is',
  '[{"id": "a", "text": "4"}, {"id": "b", "text": "2"}, {"id": "c", "text": "5"}, {"id": "d", "text": "1.5"}]'::jsonb, 'b', 'The mean is 5 and the squared deviations are 9, 1, 1, 1, 0, 0, 4 and 16, which total 32. The variance is 32 / 8 = 4, so the standard deviation is 2. The figure 4 is the variance. The value 4 is the variance, 5 is the mean, and 1.5 does not arise from the calculation.', 4,
  'medicine/sta201', 'q005'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q005')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Abstract / Visual']::text[], 'IQ scores are normally distributed with mean 100 and standard deviation 15. About what percentage of people score between 70 and 130?',
  '[{"id": "a", "text": "95%"}, {"id": "b", "text": "68%"}, {"id": "c", "text": "99.7%"}, {"id": "d", "text": "50%"}]'::jsonb, 'a', 'The range is the mean plus or minus 2 standard deviations, which covers about 95%. The value 68% corresponds to plus or minus 1 standard deviation. The value 99.7% corresponds to three standard deviations, and 50% is the share above the mean.', 3,
  'medicine/sta201', 'q006'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q006')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Essential / definitive']::text[], 'In a positively skewed distribution, such as the length of hospital stay,',
  '[{"id": "a", "text": "the mean is less than the median"}, {"id": "b", "text": "the mean equals the median"}, {"id": "c", "text": "the mode is always the largest value"}, {"id": "d", "text": "the mean is greater than the median"}]'::jsonb, 'd', 'A long tail of high values pulls the mean upwards. That is why the median is often preferred for skewed data. A mean below the median points to a negative skew, and equal values point to a symmetrical distribution.', 3,
  'medicine/sta201', 'q007'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q007')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'A sample of 100 patients has a standard deviation of 20 mmHg. The standard error of the mean is',
  '[{"id": "a", "text": "20 mmHg"}, {"id": "b", "text": "0.2 mmHg"}, {"id": "c", "text": "2 mmHg"}, {"id": "d", "text": "200 mmHg"}]'::jsonb, 'c', 'SE = s / sqrt(n) = 20 / 10 = 2 mmHg. Using the standard deviation itself ignores the sample size. The value 0.2 mmHg divides by n instead of by its square root.', 3,
  'medicine/sta201', 'q008'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q008')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'A sample mean is 50 with a standard error of 2. The approximate 95% confidence interval for the population mean is',
  '[{"id": "a", "text": "48 to 52"}, {"id": "b", "text": "44 to 56"}, {"id": "c", "text": "46.1 to 53.9"}, {"id": "d", "text": "49 to 51"}]'::jsonb, 'c', 'The interval is 50 plus or minus 1.96 x 2 = 50 plus or minus 3.92, giving 46.1 to 53.9. The 48 to 52 interval is only 1 standard error either side, which is about 68%.', 4,
  'medicine/sta201', 'q009'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q009')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Logical']::text[], array['Essential / definitive']::text[], 'A Type I error occurs when',
  '[{"id": "a", "text": "a false null hypothesis is not rejected"}, {"id": "b", "text": "a true null hypothesis is rejected"}, {"id": "c", "text": "the sample size is too large"}, {"id": "d", "text": "the data are not normally distributed"}]'::jsonb, 'b', 'A Type I error is a false positive, and its probability is alpha. Failing to reject a false null hypothesis is a Type II error.', 3,
  'medicine/sta201', 'q010'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q010')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Essential / definitive']::text[], 'A study reports p = 0.03. This means that',
  '[{"id": "a", "text": "if the null hypothesis were true, a result this extreme would occur in about 3% of studies"}, {"id": "b", "text": "there is a 3% chance that the null hypothesis is true"}, {"id": "c", "text": "the effect is 3% of the control value"}, {"id": "d", "text": "the study has 97% power"}]'::jsonb, 'a', 'The p-value is a probability of the data given the null, not the probability that the null is true. The result is conventionally called significant at the 5% level.', 4,
  'medicine/sta201', 'q011'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q011')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'A test is applied to 300 people: 90 true positives, 40 false positives, 10 false negatives and 160 true negatives. The sensitivity is',
  '[{"id": "a", "text": "80%"}, {"id": "b", "text": "69%"}, {"id": "c", "text": "94%"}, {"id": "d", "text": "90%"}]'::jsonb, 'd', 'Sensitivity = TP / (TP + FN) = 90 / 100 = 90%. The value 80% is the specificity. The value 69% is the positive predictive value, 90 / 130, and 94% is the negative predictive value, 160 / 170.', 3,
  'medicine/sta201', 'q012'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q012')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'Using the same results (90 true positives, 40 false positives, 10 false negatives, 160 true negatives), the specificity is',
  '[{"id": "a", "text": "90%"}, {"id": "b", "text": "69%"}, {"id": "c", "text": "75%"}, {"id": "d", "text": "80%"}]'::jsonb, 'd', 'Specificity = TN / (TN + FP) = 160 / 200 = 80%. The value 90% is the sensitivity, the nearest wrong choice.', 3,
  'medicine/sta201', 'q013'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q013')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'Using the same results (90 true positives, 40 false positives, 10 false negatives, 160 true negatives), the positive predictive value is about',
  '[{"id": "a", "text": "90%"}, {"id": "b", "text": "80%"}, {"id": "c", "text": "69%"}, {"id": "d", "text": "94%"}]'::jsonb, 'c', 'PPV = TP / (TP + FP) = 90 / 130 = 69%. The predictive value depends on how common the disease is in the people tested, unlike sensitivity.', 4,
  'medicine/sta201', 'q014'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q014')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Procedural / supply chain']::text[], 'To compare the mean systolic blood pressure of two independent groups, with approximately normal data, the appropriate test is the',
  '[{"id": "a", "text": "chi-squared test"}, {"id": "b", "text": "independent-samples t-test"}, {"id": "c", "text": "paired t-test"}, {"id": "d", "text": "Pearson correlation"}]'::jsonb, 'b', 'A t-test compares two means, and the groups are independent because they are different people. The chi-squared test is for categorical data, and the paired test is for the same people measured twice.', 3,
  'medicine/sta201', 'q015'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q015')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'A correlation coefficient of r = 0.8 means that the proportion of variance in one variable explained by the other is',
  '[{"id": "a", "text": "64%"}, {"id": "b", "text": "80%"}, {"id": "c", "text": "8%"}, {"id": "d", "text": "0.8%"}]'::jsonb, 'a', 'The coefficient of determination is r squared = 0.64. A value of 80% would result from reading r itself as the proportion.', 4,
  'medicine/sta201', 'q016'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q016')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'In a population of 10,000 people at risk, 20 new cases of a disease appear in one year. The incidence is',
  '[{"id": "a", "text": "2 per 1,000 per year"}, {"id": "b", "text": "20 per 1,000 per year"}, {"id": "c", "text": "0.2 per 1,000 per year"}, {"id": "d", "text": "2 per 100 per year"}]'::jsonb, 'a', 'Incidence = 20 / 10,000 = 0.002, which is 2 per 1,000. Prevalence, on the other hand, counts all existing cases, new and old. The value 20 per 1,000 is ten times too large, and 0.2 per 1,000 is ten times too small.', 3,
  'medicine/sta201', 'q017'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q017')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Mathematical Proofs']::text[], 'In a cohort study, 20 of 100 exposed people and 10 of 100 unexposed people develop the disease. The relative risk is',
  '[{"id": "a", "text": "0.5"}, {"id": "b", "text": "10"}, {"id": "c", "text": "1.1"}, {"id": "d", "text": "2.0"}]'::jsonb, 'd', 'RR = 0.20 / 0.10 = 2.0, so the exposed group has twice the risk. The value 0.5 inverts the ratio. The value 10 is the difference in risk in percentage points, not the ratio.', 3,
  'medicine/sta201', 'q018'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q018')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Statistical / Predictive']::text[], array['Essential / definitive']::text[], 'Which measure of spread is LEAST affected by extreme outliers?',
  '[{"id": "a", "text": "Range"}, {"id": "b", "text": "Standard deviation"}, {"id": "c", "text": "Interquartile range"}, {"id": "d", "text": "Variance"}]'::jsonb, 'c', 'The interquartile range uses the middle half of the data, so extreme values do not change it. The range depends on the two extremes alone.', 3,
  'medicine/sta201', 'q019'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q019')
order by c.id limit 1;

insert into cgpa.keystone_questions
  (course_id, cognitive_patterns, information_types, prompt, options, correct_option_id, explanation, difficulty, depot_key, depot_qid)
select c.id, array['Pure Mathematical']::text[], array['Mathematical Proofs']::text[], 'In a normal distribution with mean 100 and standard deviation 15, the z-score of a value of 130 is',
  '[{"id": "a", "text": "30"}, {"id": "b", "text": "2"}, {"id": "c", "text": "0.5"}, {"id": "d", "text": "8.7"}]'::jsonb, 'b', 'z = (x - mean) / SD = (130 - 100) / 15 = 2, so the value is two standard deviations above the mean. The figure 30 is the raw difference.', 3,
  'medicine/sta201', 'q020'
from cgpa.courses c
join cgpa.departments d on d.id = c.department_id
join cgpa.faculties f on f.id = d.faculty_id
where f.slug = 'medicine' and d.slug = 'medical-laboratory-science' and c.slug = 'sta201' and c.approval_status = 'approved'
  and not exists (select 1 from cgpa.keystone_questions k where k.depot_key = 'medicine/sta201' and k.depot_qid = 'q020')
order by c.id limit 1;

